Translate("zhCN", "medivh", {
	title = "麦迪文",
	subtitle = "最后的提瑞斯法守护者",
	allegiance = "提瑞斯法议会 · 卡拉赞",
	sections = {
		{
			title = "概述",
			text = [=[麦迪文是最后一位{link:tirisfal-glades}提瑞斯法{/link}守护者，是世上最睿智的法师们赋予力量、用以对抗{link:burning-legion}燃烧军团{/link}的秘密勇士。他是守护者{link:aegwynn}艾格文{/link}与{link:stormwind-city}暴风城{/link}宫廷法师尼尔拉斯·埃兰之子。他也是{link:llane-wrynn}莱恩·乌瑞恩{/link}国王和{link:anduin-lothar}安度因·洛萨{/link}爵士最亲密的朋友。然而，那本应守护{link:azeroth}艾泽拉斯{/link}的力量，在他呼吸第一口气之前就已被毒化，而为{link:orcs}兽人{/link}的到来打开道路的，正是麦迪文。]=],
		},
		{
			title = "意义",
			text = [=[没有哪个凡人比他更多地促成了这个战争时代。通过麦迪文，恶魔领主{link:sargeras}萨格拉斯{/link}把手伸进了这个世界，驱使{link:horde}部落{/link}扑向{link:humans}人类{/link}诸王国。{link:first-war}第一次战争{/link}、{link:stormwind-city}暴风城{/link}的陷落以及随后的每一场战争，其根源都可追溯到他所居住的那座高塔。]=],
		},
		{
			title = "被毒化的降生",
			text = [=[{link:aegwynn}艾格文{/link}希望她的儿子成为她的继承人，不受那个曾试图支配她的{link:shadow-council}议会{/link}的控制。她不知道，自从她击倒{link:sargeras}萨格拉斯{/link}化身的那一天起，他的灵魂便一直藏在她体内。麦迪文受孕之时，恶魔领主进入了这个尚未出世的孩子体内。男孩长大后聪慧而温和，与{link:raene-wolfrunner}莱恩{/link}和{link:anduin-lothar}洛萨{/link}一同在王国的森林中游荡。十四岁时，守护者的力量在他体内苏醒，随之苏醒的还有潜藏其下的黑暗。麦迪文陷入了一场任何医者都无法打破的沉睡。多年来，他一直躺在{link:northshire-abbey}北郡修道院{/link}的牧师们的照料之下。当他醒来时，他已长成一个男人，而对于他在黑暗中看到的东西，他只字不提。]=],
		},
		{
			title = "卡拉赞",
			text = [=[麦迪文在{link:karazhan}卡拉赞{/link}安了家，那是如今名为{link:deadwind-pass}逆风小径{/link}的土地上一座孤寂的高塔。在那里，在他体内那个意志的指引下，他穿过虚空，触及一个名为{red:draenor}德拉诺{/red}的垂死世界。他找到了{link:orcs}兽人{/link}术士{link:gul-dan}古尔丹{/link}，他们一同打开了{link:dark-portal}黑暗之门{/link}。{link:dalaran}达拉然{/link}的{link:kirin-tor}肯瑞托{/link}给他派来一名年轻的学徒{link:khadgar}卡德加{/link}，卡德加对他在塔中所见渐生恐惧。半兽人{link:garona}迦罗娜{/link}也作为{link:horde}部落{/link}的使者来到了卡拉赞。通过卡德加和迦罗娜，真相终于传到了{link:stormwind-city}暴风城{/link}。]=],
		},
		{
			title = "事迹",
			text = [=[• 年轻时，他与{link:raene-wolfrunner}莱恩{/link}和{link:anduin-lothar}洛萨{/link}并肩，用他的力量对抗南方的{link:trolls}巨魔{/link}。
• 他与{link:gul-dan}古尔丹{/link}和德拉诺的术士们一同打开了{link:dark-portal}黑暗之门{/link}。
• 他收{link:khadgar}卡德加{/link}为学徒，并让他学到了比自己本想透露的更多的东西。
• 他在自己的塔中看着{link:horde}部落{/link}焚毁他最老的朋友们的王国。]=],
		},
		{
			title = "结局",
			text = [=[{link:anduin-lothar}安度因·洛萨{/link}和{link:khadgar}卡德加{/link}登上{link:karazhan}卡拉赞{/link}，要从根源上结束这场战争。在{link:garona}迦罗娜{/link}的帮助下，他们与守护者对峙，麦迪文在那里被杀。在他临死的那一刻，{link:gul-dan}古尔丹{/link}试图从他垂死的心智中夺取{link:sargeras}萨格拉斯{/link}之墓的秘密，结果为此陷入了长久的昏迷。麦迪文死了。他的高塔空寂无声地矗立在{link:deadwind-pass}逆风小径{/link}之上，{link:duskwood}暮色森林{/link}的人们说，它的窗户里仍亮着奇异的光。]=],
		},
		{
			title = "无从记载",
			text = [=[麦迪文知道什么，他自己选择了什么，{link:sargeras}萨格拉斯{/link}又替他选择了什么，如今已无法分辨。编年史对这个问题未下定论。]=],
		},
	},
	bonds = {
		{ id = "aegwynn", name = "艾格文", note = "他的母亲" },
		{ id = "llane-wrynn", name = "莱恩·乌瑞恩", note = "他儿时的朋友" },
		{ id = "anduin-lothar", name = "安度因·洛萨", note = "他的朋友，也是杀死他的人" },
		{ id = "gul-dan", name = "古尔丹", note = "与他一同打开了黑暗之门" },
		{ id = "khadgar", name = "卡德加", note = "他的学徒" },
	},
})

Translate("zhCN", "aegwynn", {
	title = "艾格文",
	subtitle = "提瑞斯法守护者",
	allegiance = "提瑞斯法议会",
	sections = {
		{
			title = "概述",
			text = [=[艾格文担任{link:tirisfal-glades}提瑞斯法{/link}守护者的时间，比大多数王国存在的时间还要长。由{link:humans}人类{/link}和{link:high-elves}精灵{/link}土地上最伟大的法师组成的提瑞斯法秘密{link:shadow-council}议会{/link}，选择她作为对抗{link:burning-legion}燃烧军团{/link}的勇士，赋予她力量和长达数个世纪的生命。人们记得她是所有守护者中最强大的一位，也是在无意之中造成最大伤害的一位。]=],
		},
		{
			title = "意义",
			text = [=[在一次胜利中，艾格文给予了军团在{link:azeroth}艾泽拉斯{/link}所遭受过的最沉重一击。就在同一时刻，她也为军团最大的胜利打开了大门。恶魔领主{link:sargeras}萨格拉斯{/link}藏在她体内，并通过她进入了她的儿子{link:medivh}麦迪文{/link}体内。]=],
		},
		{
			title = "守护者",
			text = [=[艾格文骄傲而无畏，她不愿做{link:shadow-council}议会{/link}的傀儡。凡是恶魔出没之处，她都去追猎，她承担守护者之职跨越了许多代人的寿命。在{red:northrend}诺森德{/red}，她发现恶魔正在猎杀北方最后的巨龙并吸取它们的魔力。在巨龙的帮助下，她消灭了那些恶魔。随后，{link:sargeras}萨格拉斯{/link}本人在一场巨大的风暴中出现在她面前。艾格文与他的化身交战，并将其杀死。她把它残破的躯体封在一座{link:great-sundering}大分裂{/link}时沉入海底的古老殿堂中，让它永远无法再起。她以为军团之主已被击败。她不知道他的灵魂已悄悄潜入了她自己体内。]=],
		},
		{
			title = "守护者的继承人",
			text = [=[在随后的漫长岁月里，艾格文与{link:shadow-council}议会{/link}日渐疏远。她认定议会的成员在干涉国王们的事务，并决心绝不让他们选择下一任守护者。她选择{link:stormwind-city}暴风城{/link}的宫廷法师尼尔拉斯·埃兰为伴侣，为他生下一个儿子。她把{link:tirisfal-glades}提瑞斯法{/link}的力量置于孩子体内，待他成年时苏醒。随后，她把男孩留给他的父亲，自己隐退于世。]=],
		},
		{
			title = "事迹",
			text = [=[• 她担任守护者之职数个世纪，在{link:eastern-kingdoms}东部王国{/link}各地消灭恶魔。
• 她保护诺森德的巨龙免遭军团猎手的毒手。
• 她杀死了{link:sargeras}萨格拉斯{/link}的化身，并把它的躯体埋葬在海底。
• 她违抗{link:tirisfal-glades}提瑞斯法{/link}{link:shadow-council}议会{/link}，选择了自己的继承人。]=],
		},
		{
			title = "结局",
			text = [=[艾格文比她亲手造就的儿子活得更久。当{link:dark-portal}黑暗之门{/link}打开、{link:horde}部落{/link}到来之时，世界才明白她的骄傲付出了什么代价。{link:medivh}麦迪文{/link}在{link:karazhan}卡拉赞{/link}倒下，守护者的传承随他而终。艾格文本人则在力量耗尽后踏上了流亡之路。{link:theramore-isle}塞拉摩{/link}的学者们私下传说，一位极具智慧的老妇人曾在{link:kalimdor}卡利姆多{/link}的荒野中住过一段时间，并为{link:jaina-proudmoore}吉安娜·普罗德摩尔{/link}女士出谋划策。很少有人知道她的名字，知道的人也守口如瓶。]=],
		},
		{ title = "无从记载", text = "史书没有说明艾格文最初是如何被选中的，也没有说明她总共担任了多少年的守护者。本条目只记录确凿无疑的事。" },
	},
	bonds = {
		{ id = "medivh", name = "麦迪文", note = "她的儿子" },
		{ id = "jaina-proudmoore", name = "吉安娜·普罗德摩尔", note = "据说曾受她指点" },
	},
})

Translate("zhCN", "llane-wrynn", {
	title = "莱恩·乌瑞恩",
	subtitle = "第一次战争时的暴风城国王",
	allegiance = "暴风王国 · 乌瑞恩家族",
	aliases = { "莱恩", "莱恩国王" },
	sections = {
		{
			title = "概述",
			text = [=[当{link:horde}部落{/link}穿过{link:dark-portal}黑暗之门{/link}而来时，莱恩·乌瑞恩是{link:stormwind-city}暴风城{/link}的国王。他是一位骄傲而勇敢的统治者，是{link:medivh}麦迪文{/link}和{link:anduin-lothar}安度因·洛萨{/link}儿时的朋友，也是{link:varian-wrynn}瓦里安·乌瑞恩{/link}国王的父亲。他带领他的人民度过了{link:first-war}第一次战争{/link}的漫长苦难，并在他的城市陷落时死于自己的要塞之中。]=],
		},
		{
			title = "意义",
			text = [=[{link:raene-wolfrunner}莱恩{/link}是旧{link:stormwind-city}暴风城{/link}的最后一位国王。他的死标志着一个孤傲地屹立了许多代的王国的终结。{link:alliance}联盟{/link}从它的废墟中诞生，因为他留下的幸存者把{link:orcs}兽人{/link}的警告带到了北方的{link:lordaeron}洛丹伦{/link}。]=],
		},
		{
			title = "少年时代",
			text = [=[{link:raene-wolfrunner}莱恩{/link}是在两个非凡男孩的陪伴下长大的：古老血脉的继承人{link:anduin-lothar}安度因·洛萨{/link}，以及宫廷法师之子{link:medivh}麦迪文{/link}。三人形影不离。麦迪文陷入长眠时，莱恩在没有他的陪伴下长大成人；他的朋友醒来时，他欣喜不已。这份友谊在日后的岁月里蒙蔽了他的双眼。]=],
		},
		{
			title = "第一次战争",
			text = [=[当黑色{link:swamp-of-sorrows}沼泽{/link}中出现奇怪的生物时，{link:raene-wolfrunner}莱恩{/link}派{link:anduin-lothar}洛萨{/link}去查明它们是什么。它们是{link:orcs}兽人{/link}，而且只是第一批。莱恩任命洛萨为他的勇士，并派信使前往其他{link:humans}人类{/link}王国，但很少有人相信这个故事。多年来，{link:stormwind-city}暴风城{/link}孤军奋战。村庄在{link:elwynn-forest}艾尔文森林{/link}、{link:westfall}西部荒野{/link}和{link:redridge-mountains}赤脊山{/link}各处燃烧。{link:horde}部落{/link}围攻都城，却被击退了，因为洛萨出其不意地袭击了它的后方。当{link:khadgar}卡德加{/link}和半兽人{link:garona}迦罗娜{/link}警告国王说，正是{link:medivh}麦迪文{/link}本人引来了入侵者时，莱恩不肯相信他的朋友会背叛他。]=],
		},
		{
			title = "事迹",
			text = [=[• 他任命{link:anduin-lothar}安度因·洛萨{/link}为王国的勇士，并把王国的防务托付给他。
• 他向其他{link:humans}人类{/link}王国发出了关于{link:orcs}兽人{/link}的警告。
• 他守住了{link:stormwind-city}暴风城{/link}，抵挡住了{link:horde}部落{/link}的第一次大围攻。
• {link:medivh}麦迪文{/link}倒下后，他把{link:garona}迦罗娜{/link}视为心腹。]=],
		},
		{
			title = "结局",
			text = [=[{link:medivh}麦迪文{/link}死后，{link:orcs}兽人{/link}{link:orgrim-doomhammer}奥格瑞姆·毁灭之锤{/link}夺取了{link:horde}部落{/link}的指挥权，再次率领部落进攻{link:stormwind-city}暴风城{/link}。城墙被攻破，但{link:raene-wolfrunner}莱恩{/link}守住了要塞。{link:garona}迦罗娜{/link}已成为他信任的谋士，却仍受部落术士意志的束缚。她在国王的寝宫中杀死了他。年幼的王子{link:varian-wrynn}瓦里安{/link}目睹了父亲之死。暴风城陷落了，部落将它夷为平地。{link:anduin-lothar}洛萨{/link}召集幸存者，率领他们渡海前往{link:lordaeron}洛丹伦{/link}。莱恩的王国后来得以重建，他的儿子一直坐在它的王座上，直到最近失踪。他的孙子{link:anduin-wrynn}安度因·乌瑞恩{/link}如今在重建的要塞中等待，他的名字取自那位拯救了他家族的勇士。]=],
		},
		{
			title = "无从记载",
			text = [=[编年史很少提及{link:raene-wolfrunner}莱恩{/link}的王后，也很少提及{link:dark-portal}黑暗之门{/link}打开之前他在位的岁月。]=],
		},
	},
	bonds = {
		{ id = "medivh", name = "麦迪文", note = "他儿时的朋友" },
		{ id = "anduin-lothar", name = "安度因·洛萨", note = "他的勇士" },
		{ id = "varian-wrynn", name = "瓦里安·乌瑞恩", note = "他的儿子" },
		{ id = "orgrim-doomhammer", name = "奥格瑞姆·毁灭之锤", note = "率领夺取他城市的部落" },
		{ id = "garona", name = "迦罗娜", note = "他的谋士，也是杀死他的人" },
	},
})

Translate("zhCN", "anduin-lothar", {
	title = "安度因·洛萨",
	subtitle = "艾泽拉斯之狮",
	allegiance = "暴风王国 · 洛丹伦联盟",
	aliases = { "洛萨", "安度因·洛萨爵士" },
	sections = {
		{
			title = "概述",
			text = [=[安度因·洛萨爵士是{link:first-war}第一次战争{/link}中{link:stormwind-city}暴风城{/link}的勇士，也是{link:second-war}第二次战争{/link}中{link:alliance}联盟{/link}的第一任最高指挥官。他是{link:arathor}阿拉索{/link}王族血脉已知的最后一位继承人，人类诸王国正是从这个古老帝国中诞生的。士兵们称他为{link:azeroth}艾泽拉斯{/link}之狮。没有他，{link:humans}人类{/link}诸国也许永远不会团结在一起。]=],
		},
		{
			title = "意义",
			text = [=[洛萨两次拯救了{link:stormwind-city}暴风城{/link}：一次是带领它的人民走出灰烬，另一次是说服北方的国王们为它而战。他所缔造的{link:alliance}联盟{/link}至今仍在，他的国王的孙子也承袭了他的名字。]=],
		},
		{
			title = "第一次战争",
			text = [=[洛萨是{link:llane-wrynn}莱恩·乌瑞恩{/link}和{link:medivh}麦迪文{/link}少年时的朋友。当{link:orcs}兽人{/link}第一次在黑色{link:swamp-of-sorrows}沼泽{/link}中出现时，国王派他去侦察，而他带回了一场战争的消息。{link:raene-wolfrunner}莱恩{/link}任命他为王国的勇士。洛萨在全国各地征战多年。当{link:horde}部落{/link}第一次围攻{link:stormwind-city}暴风城{/link}时，他率领王国的骑士们从海路绕过敌军，袭击其后方，击溃了这次进攻。他与年轻的法师{link:khadgar}卡德加{/link}一同登上{link:karazhan}卡拉赞{/link}，面对他最老的朋友麦迪文，守护者在那里被杀。然而王国已无法挽救。暴风城陷落时，洛萨率领幸存者向北渡海而去。]=],
		},
		{
			title = "第二次战争",
			text = [=[在{link:lordaeron}洛丹伦{/link}，洛萨站在{link:terenas-menethil}泰瑞纳斯·米奈希尔{/link}国王和北方诸国的领主们面前，警告他们{link:horde}部落{/link}下一个目标就是他们。他们听进去了。{link:alliance}洛丹伦联盟{/link}由此诞生，洛萨被任命为它的指挥官。{link:quel-thalas}奎尔萨拉斯{/link}的{link:high-elves}高等精灵{/link}加入了联盟，因为他们欠{link:arathor}阿拉索{/link}血脉一笔古老的恩债，而洛萨正是这一血脉最后的继承人。他以{link:khadgar}卡德加{/link}和年轻的圣骑士{link:turalyon}图拉扬{/link}为副手，在北方诸王国与部落作战，将其击退至南方。]=],
		},
		{
			title = "事迹",
			text = [=[• 他在黑色{link:swamp-of-sorrows}沼泽{/link}侦察到最早的{link:orcs}兽人{/link}，并警告了他的国王。
• 他从海上发起冲锋，打破了{link:stormwind-city}暴风城{/link}的第一次围攻。
• 他在{link:khadgar}卡德加{/link}的陪同下，于{link:karazhan}卡拉赞{/link}杀死了{link:medivh}麦迪文{/link}。
• 他带领暴风城的人民流亡到{link:lordaeron}洛丹伦{/link}。
• 他说服{link:humans}人类{/link}诸王国团结起来，并指挥他们的军队。]=],
		},
		{
			title = "结局",
			text = [=[{link:second-war}第二次战争{/link}末期，洛萨追击{link:horde}部落{/link}至{link:burning-steppes}燃烧平原{/link}的{link:blackrock-mountain}黑石山{/link}。在那里，在山脚下的战斗中，他死于{link:orgrim-doomhammer}奥格瑞姆·毁灭之锤{/link}之手。他的死没有击垮{link:alliance}联盟{/link}。{link:turalyon}图拉扬{/link}拾起了他的剑，重振悲痛的士兵，击溃了部落。{link:stormwind-city}暴风城{/link}被收复，{link:varian-wrynn}瓦里安·乌瑞恩{/link}国王后来为纪念这位勇士，给自己的儿子取名为安度因。]=],
		},
	},
	bonds = {
		{ id = "llane-wrynn", name = "莱恩·乌瑞恩", note = "他的国王和朋友" },
		{ id = "medivh", name = "麦迪文", note = "他的朋友，也是他的敌人" },
		{ id = "terenas-menethil", name = "泰瑞纳斯·米奈希尔", note = "授予他联盟的指挥权" },
		{ id = "orgrim-doomhammer", name = "奥格瑞姆·毁灭之锤", note = "杀死他的人" },
		{ id = "turalyon", name = "图拉扬", note = "他的副手和继任者" },
		{ id = "anduin-wrynn", name = "安度因·乌瑞恩", note = "以他的名字命名" },
	},
})

Translate("zhCN", "tiffin-wrynn", {
	title = "蒂芬·乌瑞恩",
	subtitle = "暴风城王后",
	allegiance = "暴风王国 · 乌瑞恩家族",
	aliases = { "蒂芬", "蒂芬王后" },
	sections = {
		{
			title = "概述",
			text = [=[蒂芬·乌瑞恩是{link:varian-wrynn}瓦里安·乌瑞恩{/link}国王的王后，{link:anduin-wrynn}安度因·乌瑞恩{/link}王子的母亲。{link:second-war}第二次战争{/link}后的那些年里，{link:stormwind-city}暴风城{/link}正从灰烬中再次崛起，她坐在瓦里安身旁。她没能活着看到城市竣工。她死于石匠暴动，成了王室贵族与重建城墙之人之间那场争执的牺牲品。]=],
		},
		{
			title = "意义",
			text = [=[蒂芬之死是新{link:stormwind-city}暴风城{/link}无声的伤口之一。它让王国的继承人失去了母亲，让国王失去了妻子。它也标志着石匠们的愤怒转为公开反叛的时刻，{link:defias-brotherhood}迪菲亚兄弟会{/link}正是由此诞生。]=],
		},
		{
			title = "重建",
			text = [=[{link:second-war}第二次战争{/link}后，{link:stormwind-city}暴风城{/link}的流亡者回到故乡，发现他们的城市已成一片废墟。{link:edwin-vancleef}艾德温·范克里夫{/link}领导的{link:stonemasons-guild}石匠工会{/link}辛劳多年，重新建起了它。{link:llane-wrynn}莱恩·乌瑞恩{/link}之子{link:varian-wrynn}瓦里安{/link}登上了先祖的王座。蒂芬成为他的王后，后来为他生下一个儿子安度因，名字取自勇士{link:anduin-lothar}安度因·洛萨{/link}。有一段时间，王国似乎可以重享和平。]=],
		},
		{
			title = "暴动",
			text = [=[{link:house-of-nobles}贵族议会{/link}曾承诺为石匠们的劳动付酬。工程完成后，贵族们却拒绝了。石匠们在都城的街道上抗议，抗议演变成了暴动。在混乱中，王后被击倒身亡。石匠们被屈辱地赶出城市，其中最怨愤的人逃到了{link:westfall}西部荒野{/link}。他们在那里戴上了红色头巾，从此他们的兄弟会便一直在掠夺这个王国。]=],
		},
		{
			title = "事迹",
			text = [=[• 在{link:stormwind-city}暴风城{/link}重建后的岁月里，她是暴风城的王后。
• 她为{link:varian-wrynn}瓦里安{/link}生下了儿子和继承人安度因。]=],
		},
		{
			title = "结局",
			text = [=[蒂芬已长眠。她的儿子还是个男孩，如今在{link:stormwind-keep}暴风要塞{/link}中等待，而他父亲的命运依然不明，大领主{link:bolvar-fordragon}伯瓦尔·弗塔根{/link}以摄政王身份统治着王国。曾经为王室效力的石匠们，如今在{link:westfall}西部荒野{/link}的矿井和农场里向王室发动着自己的战争。{link:stormwind-city}暴风城{/link}中仍有许多人怀着爱意谈起王后，又怀着羞愧谈起她的死。]=],
		},
		{
			title = "无从记载",
			text = [=[关于蒂芬成为王后之前的生平，记载甚少。编年史记录了她的婚姻、她的儿子和她的死，却几乎没有记录她自己的言行。本条目不以猜测去填补这片沉默。]=],
		},
	},
	bonds = {
		{ id = "varian-wrynn", name = "瓦里安·乌瑞恩", note = "她的丈夫" },
		{ id = "anduin-wrynn", name = "安度因·乌瑞恩", note = "她的儿子" },
		{ id = "llane-wrynn", name = "莱恩·乌瑞恩", note = "她丈夫的父亲" },
		{ id = "edwin-vancleef", name = "艾德温·范克里夫", note = "领导了夺走她生命的石匠暴动" },
	},
})

Translate("zhCN", "terenas-menethil", {
	title = "泰瑞纳斯·米奈希尔",
	subtitle = "洛丹伦国王",
	allegiance = "洛丹伦王国 · 洛丹伦联盟",
	aliases = { "泰瑞纳斯", "泰瑞纳斯国王" },
	sections = {
		{
			title = "概述",
			text = [=[泰瑞纳斯·米奈希尔二世国王统治着{link:lordaeron}洛丹伦{/link}，北方{link:humans}人类{/link}王国中最伟大的一个。{link:alliance}联盟{/link}是在他的都城建立的，{link:second-war}第二次战争{/link}中{link:horde}部落{/link}也是在他的旗帜下被击败的。他是{link:arthas-menethil}阿尔萨斯·米奈希尔{/link}王子和卡莉娅公主的父亲。他死于儿子之手，他的王国也随他一同死去。]=],
		},
		{
			title = "意义",
			text = [=[泰瑞纳斯是{link:alliance}洛丹伦联盟{/link}的基石。他收留了{link:stormwind-city}暴风城{/link}的难民，在其他国王不愿倾听时倾听了{link:anduin-lothar}安度因·洛萨{/link}的话。然而，他的胜利之后的和平在他的统治下渐渐瓦解，他的王国最终的命运是{link:humans}人类{/link}历史上最黑暗的一页。]=],
		},
		{
			title = "联盟",
			text = [=[当{link:anduin-lothar}洛萨{/link}把{link:stormwind-city}暴风城{/link}的流亡者带到北方时，泰瑞纳斯召集{link:humans}人类{/link}诸国的领主前来他的都城。{link:gilneas}吉尔尼斯{/link}、{link:kul-tiras}库尔提拉斯{/link}、{link:stromgarde-keep}激流堡{/link}、{link:alterac-mountains}奥特兰克{/link}和{link:dalaran}达拉然{/link}派来了他们的统治者和使节，{link:quel-thalas}奎尔萨拉斯{/link}的{link:high-elves}高等精灵{/link}后来也加入了他们。泰瑞纳斯把联军的指挥权交给了洛萨。{link:lordaeron}洛丹伦{/link}自己的土地在战争中饱受摧残，但最终{link:horde}部落{/link}被击溃，{link:orcs}兽人{/link}沦为俘虏。]=],
		},
		{
			title = "瓦解的和平",
			text = [=[战后，泰瑞纳斯下令把被俘的{link:orcs}兽人{/link}关押在巨大的{link:internment-camps}收容所{/link}中。收容所耗资巨大，他向其他国家征税来支付开销。围绕收容所和奸诈的{link:alterac-mountains}奥特兰克王国{/link}的命运，争执日益加剧。{link:gilneas}吉尔尼斯{/link}、{link:stromgarde-keep}激流堡{/link}和{link:quel-thalas}奎尔萨拉斯{/link}相继退出了{link:alliance}联盟{/link}。当一场奇怪的瘟疫开始在{link:lordaeron}洛丹伦{/link}北部的农田中蔓延时，国王派他的儿子{link:arthas-menethil}阿尔萨斯{/link}和圣骑士{link:uther-the-lightbringer}光明使者乌瑟尔{/link}去终结它。]=],
		},
		{
			title = "事迹",
			text = [=[• 他欢迎{link:stormwind-city}暴风城{/link}的难民进入他的王国。
• 他建立了{link:alliance}洛丹伦联盟{/link}，并把指挥权交给{link:anduin-lothar}安度因·洛萨{/link}。
• {link:second-war}第二次战争{/link}后，他下令修建{link:internment-camps}收容所{/link}。
• 他派{link:arthas-menethil}阿尔萨斯{/link}和{link:uther-the-lightbringer}乌瑟尔{/link}去对付北方的瘟疫。]=],
		},
		{
			title = "结局",
			text = [=[{link:arthas-menethil}阿尔萨斯{/link}作为英雄从{red:northrend}诺森德{/red}归来，都城的人民在他的路上撒满了花瓣。王子走进王座大厅，跪在父亲面前，随后用符文剑{red:frostmourne}霜之哀伤{/red}杀死了他。国王一死，王国便落入了{link:scourge}天灾军团{/link}之手。{link:uther-the-lightbringer}乌瑟尔{/link}后来护送装有国王骨灰的骨灰瓮前往{link:quel-thalas}奎尔萨拉斯{/link}，但阿尔萨斯杀死了这位圣骑士，把骨灰抛撒一旁。泰瑞纳斯的都城已成废墟，{link:sylvanas-windrunner}希尔瓦娜斯·风行者{/link}女士的{link:forsaken}被遗忘者{/link}在它的地下建起了{link:undercity}幽暗城{/link}。]=],
		},
	},
	bonds = {
		{ id = "arthas-menethil", name = "阿尔萨斯·米奈希尔", note = "他的儿子，也是杀害他的凶手" },
		{ id = "anduin-lothar", name = "安度因·洛萨", note = "他的联盟的指挥官" },
		{ id = "uther-the-lightbringer", name = "光明使者乌瑟尔", note = "他忠诚的圣骑士" },
		{ id = "alonsus-faol", name = "阿隆索斯·法奥", note = "他所信奉之教的大主教" },
	},
})

Translate("zhCN", "arthas-menethil", {
	title = "阿尔萨斯·米奈希尔",
	subtitle = "堕落的王子",
	allegiance = "天灾军团（曾属洛丹伦王国、白银之手骑士团）",
	aliases = { "阿尔萨斯", "阿尔萨斯王子" },
	sections = {
		{
			title = "概述",
			text = [=[阿尔萨斯·米奈希尔是{link:lordaeron}洛丹伦{/link}的王储，白银之手的骑士，{link:uther-the-lightbringer}光明使者乌瑟尔{/link}的学生。他勇敢、受人爱戴，又骄傲自负。他出发去拯救他的人民免受亡灵瘟疫之害，最终却毁灭了他们。他杀害了自己的父亲{link:terenas-menethil}泰瑞纳斯·米奈希尔{/link}国王，率领{link:scourge}天灾军团{/link}横扫北方。如今他在{red:northrend}诺森德{/red}冰封的中心统治着亡灵。]=],
		},
		{
			title = "意义",
			text = [=[在{link:humans}人类{/link}历史上，没有哪一次堕落如此深重、如此可怕。在每一片曾经属于{link:alliance}联盟{/link}的土地上，阿尔萨斯的名字都遭人诅咒，他所蹂躏的土地至今仍被称为瘟疫之地。]=],
		},
		{
			title = "王子",
			text = [=[阿尔萨斯是{link:terenas-menethil}泰瑞纳斯{/link}唯一的儿子。{link:uther-the-lightbringer}乌瑟尔{/link}把他训练成一名{link:holy-light}圣光{/link}圣骑士，他被白银之手骑士团接纳。当一场瘟疫袭击{link:lordaeron}洛丹伦{/link}北部的农田时，国王派阿尔萨斯和乌瑟尔去终结它。在{link:dalaran}达拉然{/link}的{link:jaina-proudmoore}吉安娜·普罗德摩尔{/link}的陪伴下，阿尔萨斯循着疫病找到了死灵法师{link:kel-thuzad}克尔苏加德{/link}和他的{link:cult-of-the-damned}诅咒教派{/link}，并杀死了他。然而瘟疫仍在蔓延。在斯坦索姆，阿尔萨斯发现城中的粮食已被污染，所有吃过的人都会变成亡灵。他下令净化这座城市。乌瑟尔和吉安娜拒绝参与，阿尔萨斯在没有他们的情况下执行了{link:culling-of-stratholme}斯坦索姆的净化{/link}。]=],
		},
		{
			title = "堕落",
			text = [=[阿尔萨斯追击恐惧魔王玛尔加尼斯到了诺森德。在那里，他烧掉了自己的船，让部下无法回头，并拿起了被诅咒的符文剑{red:frostmourne}霜之哀伤{/red}。他用它杀死了玛尔加尼斯，但这把剑夺走了他的灵魂。他作为{red:lich-king}巫妖王{/red}的仆从回到了{link:lordaeron}洛丹伦{/link}。他在王座大厅中杀害了父亲，王国随之陷落。他摧毁了白银之手骑士团，杀死了{link:uther-the-lightbringer}乌瑟尔{/link}，在蹂躏{link:quel-thalas}奎尔萨拉斯{/link}之后，于太阳之井旁复活了{link:kel-thuzad}克尔苏加德{/link}。他杀死了游侠将军{link:sylvanas-windrunner}希尔瓦娜斯·风行者{/link}，并把她的灵魂束缚在自己的意志之下。]=],
		},
		{
			title = "事迹",
			text = [=[• 他执行了{link:culling-of-stratholme}斯坦索姆的净化{/link}。
• 他杀害了{link:terenas-menethil}泰瑞纳斯国王{/link}，把{link:lordaeron}洛丹伦{/link}交给了{link:scourge}天灾军团{/link}。
• 他杀死了{link:uther-the-lightbringer}光明使者乌瑟尔{/link}。
• 他蹂躏了{link:quel-thalas}奎尔萨拉斯{/link}，并玷污太阳之井，将{link:kel-thuzad}克尔苏加德{/link}复活为巫妖。
• 他为{link:burning-legion}燃烧军团{/link}打开了通往{link:dalaran}达拉然{/link}的道路。]=],
		},
		{
			title = "结局",
			text = [=[{link:battle-of-mount-hyjal}海加尔山之战{/link}后，巫妖王的力量衰退，阿尔萨斯失去了对{link:lordaeron}洛丹伦{/link}的掌控。{link:sylvanas-windrunner}希尔瓦娜斯{/link}挣脱了他的控制，{link:forsaken}被遗忘者{/link}起来反抗他。应他主人的召唤，阿尔萨斯回到了诺森德。在冰冠冰川，他与{link:illidan-stormrage}伊利丹·怒风{/link}交战并击败了他。随后他登上冰封王座，戴上了巫妖王的头盔，两者合而为一。阿尔萨斯如今作为巫妖王统治着诺森德。在洛丹伦，{link:kel-thuzad}克尔苏加德{/link}以他的名义指挥着{link:scourge}天灾军团{/link}。曾随他北上的{link:muradin-bronzebeard}穆拉丁·铜须{/link}再也没有回家。]=],
		},
	},
	bonds = {
		{ id = "terenas-menethil", name = "泰瑞纳斯·米奈希尔", note = "他的父亲，也是他的受害者" },
		{ id = "uther-the-lightbringer", name = "光明使者乌瑟尔", note = "他的导师，也是他的受害者" },
		{ id = "jaina-proudmoore", name = "吉安娜·普罗德摩尔", note = "他失去的爱人" },
		{ id = "kel-thuzad", name = "克尔苏加德", note = "先是敌人，后为仆从" },
		{ id = "ner-zhul", name = "耐奥祖", note = "他与之结合的巫妖王" },
		{ id = "illidan-stormrage", name = "伊利丹·怒风", note = "冰冠冰川的敌人" },
		{ id = "sylvanas-windrunner", name = "希尔瓦娜斯·风行者", note = "他的受害者和敌人" },
	},
})

Translate("zhCN", "uther-the-lightbringer", {
	title = "光明使者乌瑟尔",
	subtitle = "第一位圣骑士",
	allegiance = "白银之手骑士团 · 圣光教会",
	aliases = { "乌瑟尔", "乌瑟尔大人" },
	sections = {
		{
			title = "概述",
			text = [=[光明使者乌瑟尔是第一位{link:holy-light}圣光{/link}圣骑士，也是白银之手骑士团的领袖。他在大主教{link:alonsus-faol}阿隆索斯·法奥{/link}身边习得信仰，在{link:second-war}第二次战争{/link}中于北方各地与{link:horde}部落{/link}作战，并训练了王子{link:arthas-menethil}阿尔萨斯·米奈希尔{/link}。他是王子的导师和朋友，最终死于王子之手。]=],
		},
		{
			title = "意义",
			text = [=[乌瑟尔向{link:humans}人类{/link}诸王国证明了信仰与钢铁可以并肩而立。他领导的骑士团保卫了{link:lordaeron}洛丹伦{/link}整整一代人，世上每一位圣骑士至今仍怀着崇敬提起他的名字。]=],
		},
		{
			title = "白银之手",
			text = [=[{link:first-war}第一次战争{/link}后，消息传到北方：{link:horde}部落{/link}屠杀了{link:northshire-abbey}北郡修道院{/link}的牧师。{link:alonsus-faol}阿隆索斯·法奥{/link}决心让{link:holy-light}圣光{/link}的仆从不再手无寸铁。在{link:anduin-lothar}安度因·洛萨{/link}的支持下，他召集了信仰坚定的战士，教他们在战斗中运用神圣的力量。乌瑟尔是其中的第一人。训练完成后，大主教任命他为新成立的白银之手骑士团的领袖。乌瑟尔和他的圣骑士们，其中包括{link:turalyon}图拉扬{/link}和{link:tirion-fordring}提里奥·弗丁{/link}，在整个{link:second-war}第二次战争{/link}中奋战，在战斗最惨烈之处带去治愈与希望。]=],
		},
		{
			title = "王子",
			text = [=[在和平的年代里，乌瑟尔收年轻的{link:arthas-menethil}阿尔萨斯{/link}为学生，把他接纳进骑士团。当{link:lordaeron}洛丹伦{/link}北部爆发瘟疫时，{link:terenas-menethil}泰瑞纳斯·米奈希尔{/link}国王派他们二人去终结它。在斯坦索姆，阿尔萨斯下令在瘟疫让城中百姓复活之前将他们杀死。乌瑟尔拒绝了。他不愿向活人下手，阿尔萨斯便解除了他的职务。{link:culling-of-stratholme}斯坦索姆的净化{/link}在没有他的情况下进行了。]=],
		},
		{
			title = "事迹",
			text = [=[• 他是{link:alonsus-faol}阿隆索斯·法奥{/link}册封的第一位圣骑士，领导白银之手骑士团。
• 他在{link:second-war}第二次战争{/link}中与{link:horde}部落{/link}作战。
• 他以{link:holy-light}圣光{/link}之道训练{link:arthas-menethil}阿尔萨斯王子{/link}。
• 他拒绝参与{link:culling-of-stratholme}斯坦索姆的净化{/link}。]=],
		},
		{
			title = "结局",
			text = [=[当{link:arthas-menethil}阿尔萨斯{/link}从{red:northrend}诺森德{/red}归来并杀害了他的父亲时，王子转而对付那个培养了他的骑士团。他摧毁了白银之手，追杀它的骑士。乌瑟尔和他最后的圣骑士们守护着装有{link:terenas-menethil}泰瑞纳斯国王{/link}骨灰的骨灰瓮。阿尔萨斯前来夺取它，学生用符文剑{red:frostmourne}霜之哀伤{/red}杀死了他的老师。如今在{link:western-plaguelands}西瘟疫之地{/link}矗立着一座纪念乌瑟尔的墓，那是死寂之地中的一处悲伤之所。他训练过的一些圣骑士仍然活着，他们记得他。]=],
		},
	},
	bonds = {
		{ id = "alonsus-faol", name = "阿隆索斯·法奥", note = "他的导师" },
		{ id = "arthas-menethil", name = "阿尔萨斯·米奈希尔", note = "他的学生，也是杀死他的人" },
		{ id = "terenas-menethil", name = "泰瑞纳斯·米奈希尔", note = "他的国王" },
		{ id = "turalyon", name = "图拉扬", note = "白银之手的兄弟" },
		{ id = "tirion-fordring", name = "提里奥·弗丁", note = "白银之手的兄弟" },
	},
})

Translate("zhCN", "alonsus-faol", {
	title = "阿隆索斯·法奥",
	subtitle = "圣光大主教",
	allegiance = "圣光教会 · 白银之手骑士团",
	aliases = { "大主教法奥", "大主教阿隆索斯·法奥" },
	sections = {
		{
			title = "概述",
			text = [=[阿隆索斯·法奥是{link:holy-light}圣光{/link}教会的大主教，{link:second-war}第二次战争{/link}时代{link:humans}人类{/link}诸王国的精神之父。他是一位矮胖的老人，白须慈颜，受到平民和国王的一致爱戴。他创立了白银之手骑士团，并册封{link:uther-the-lightbringer}光明使者乌瑟尔{/link}为第一位圣骑士。]=],
		},
		{
			title = "意义",
			text = [=[在法奥之前，{link:holy-light}圣光{/link}的仆从在别人作战时治疗和祈祷。在他之后，他们骑马奔赴战场。每一片{link:humans}人类{/link}土地上的圣骑士组织，以及如今在{link:northshire-abbey}北郡修道院{/link}受训的年轻圣骑士，都走在他开辟的道路上。]=],
		},
		{
			title = "白银之手",
			text = [=[法奥长期侍奉信仰，早在{link:orcs}兽人{/link}到来的许多年前，他就收年轻的{link:uther-the-lightbringer}乌瑟尔{/link}为学徒。{link:first-war}第一次战争{/link}期间，{link:horde}部落{/link}焚毁了{link:northshire-abbey}北郡修道院{/link}，屠杀了那里的牧师。当{link:stormwind-city}暴风城{/link}的幸存者抵达{link:lordaeron}洛丹伦{/link}时，大主教听说了这场屠杀，决心不让它重演。他与{link:anduin-lothar}安度因·洛萨{/link}一同创立了一个神圣战士的组织。他挑选信仰坚定的骑士，教他们在战斗中召唤{link:holy-light}圣光{/link}。乌瑟尔、{link:turalyon}图拉扬{/link}、{link:tirion-fordring}提里奥·弗丁{/link}等少数几人是第一批。训练完成后，法奥任命乌瑟尔为白银之手骑士团的领袖。]=],
		},
		{
			title = "和平年代",
			text = [=[{link:humans}人类{/link}诸国的领主们在{link:lordaeron}洛丹伦{/link}都城会晤时，法奥也在场。据说当他们的争吵愈演愈烈时，是他帮助他们保持冷静。战后，他把心思转向了南方的重建。他把牧师和圣骑士派往一切需要他们的地方，并支持在{link:stormwind-city}暴风城{/link}修建新的{link:cathedral-of-light}圣光大教堂{/link}和修复{link:northshire-abbey}北郡{/link}。]=],
		},
		{
			title = "事迹",
			text = [=[• 他以{link:holy-light}圣光{/link}的信仰教导{link:uther-the-lightbringer}乌瑟尔{/link}。
• 他与{link:anduin-lothar}安度因·洛萨{/link}一同创立了白银之手骑士团。
• 他册封了第一批圣骑士，并任命乌瑟尔为他们的领袖。
• {link:second-war}第二次战争{/link}期间，他为{link:alliance}联盟{/link}的领主们出谋划策。
• 他协助重建{link:stormwind-city}暴风城{/link}和{link:northshire-abbey}北郡修道院{/link}。]=],
		},
		{
			title = "结局",
			text = [=[法奥在{link:second-war}第二次战争{/link}后的岁月里去世。编年史没有说明他是怎么死的。他的学生{link:archbishop-benedictus}本尼迪塔斯{/link}继任大主教，至今仍主持着{link:stormwind-city}暴风城{/link}的{link:cathedral-of-light}圣光大教堂{/link}。法奥被安葬在{link:tirisfal-glades}提瑞斯法林地{/link}一座名为法奥之墓的陵墓中。那片土地如今属于亡灵，{link:forsaken}被遗忘者{/link}行走在信徒们曾来祈祷的地方。]=],
		},
		{ title = "无从记载", text = "没有任何编年史讲述阿隆索斯·法奥是如何、在何时去世的。对于他成为大主教之前的生平，也记载不多。" },
	},
	bonds = {
		{ id = "uther-the-lightbringer", name = "光明使者乌瑟尔", note = "他的学徒" },
		{ id = "anduin-lothar", name = "安度因·洛萨", note = "与他一同创立白银之手" },
		{ id = "terenas-menethil", name = "泰瑞纳斯·米奈希尔", note = "他在洛丹伦的国王" },
	},
})

Translate("zhCN", "orgrim-doomhammer", {
	title = "奥格瑞姆·毁灭之锤",
	subtitle = "第二次战争时的部落大酋长",
	allegiance = "部落 · 黑石氏族",
	aliases = { "奥格瑞姆", "大酋长毁灭之锤" },
	sections = {
		{
			title = "概述",
			text = [=[奥格瑞姆·毁灭之锤是征服{link:stormwind-city}暴风城{/link}、并在{link:second-war}第二次战争{/link}中率领{link:orcs}兽人{/link}的{link:horde}部落{/link}大酋长。他是{link:blackrock-clan}黑石氏族{/link}的战士，他家族那把巨锤的持有者，也是{link:frostwolf-clan}霜狼氏族{/link}杜隆坦最老的朋友。他憎恨那些腐化了他的族人的术士，并以他自己的方式试图让族人获得自由。在生命的尽头，他找到了那个将完成这项事业的兽人：{link:thrall}萨尔{/link}。]=],
		},
		{
			title = "意义",
			text = [=[毁灭之锤让{link:horde}部落{/link}成为一支意志统一的军队。在他的率领下，部落比以往任何时候都更接近征服{link:humans}人类{/link}诸王国。然而，他最伟大的遗产并不是一场征服。那是新的部落，而它的都城{link:orgrimmar}奥格瑞玛{/link}就以他的名字命名。]=],
		},
		{
			title = "第一次战争",
			text = [=[在战争初期，奥格瑞姆担任大酋长黑手的副手，而黑手是术士{link:gul-dan}古尔丹{/link}的傀儡。当杜隆坦被古尔丹的刺客杀害后，奥格瑞姆的怒火再也无法遏制。{link:medivh}麦迪文{/link}死后，他向黑手发起了一场生死决斗，用毁灭之锤砸碎了他的头颅。成为大酋长后，他禁止使用那毒害了德拉诺的黑暗魔法。他再次率领{link:horde}部落{/link}进攻{link:stormwind-city}暴风城{/link}，这一次城市陷落了。随后，他找到了术士们的{link:shadow-council}暗影议会{/link}的巢穴，屠杀了其中的大多数人。]=],
		},
		{
			title = "第二次战争",
			text = [=[毁灭之锤饶了{link:gul-dan}古尔丹{/link}一命，因为古尔丹答应给他新的武器。他召集{link:horde}部落{/link}的全部力量，向北进军。他夺取了卡兹莫丹的{link:kingdom-of-ironforge}矮人土地{/link}，与阿曼尼森林{link:trolls}巨魔{/link}结盟，并在战斗中驱使{link:dragonmaw-clan}龙喉氏族{/link}的红龙。他的大军焚烧了{link:quel-thalas}奎尔萨拉斯{/link}的森林，围攻{link:lordaeron}洛丹伦{/link}的都城。随后，古尔丹背叛了他，带走了大部分部落。围攻失败了。在{link:blackrock-mountain}黑石山{/link}，毁灭之锤在战斗中杀死了{link:anduin-lothar}安度因·洛萨{/link}，但圣骑士{link:turalyon}图拉扬{/link}重振了{link:alliance}联盟{/link}，部落被击溃。]=],
		},
		{
			title = "事迹",
			text = [=[• 他杀死黑手，自立为大酋长。
• 他征服了{link:stormwind-city}暴风城{/link}，结束了{link:first-war}第一次战争{/link}。
• 他摧毁了{link:shadow-council}暗影议会{/link}。
• 他率领{link:horde}部落{/link}打到了{link:lordaeron}洛丹伦{/link}都城的城门前。
• 他在{link:blackrock-mountain}黑石山{/link}杀死了{link:anduin-lothar}安度因·洛萨{/link}。]=],
		},
		{
			title = "结局",
			text = [=[毁灭之锤被俘，戴着镣铐在{link:lordaeron}洛丹伦{/link}都城示众。他逃了出来，隐居多年。当杜隆坦之子、年轻的{link:thrall}萨尔{/link}找到他时，这位老酋长一眼就认出了他。他与萨尔一同解放{link:internment-camps}收容所{/link}中的{link:orcs}兽人{/link}，并在{link:hillsbrad-foothills}希尔斯布莱德{/link}丘陵的一场战斗中倒下。临死前，他任命萨尔为新的大酋长。萨尔如今在{link:orgrimmar}奥格瑞玛{/link}身穿毁灭之锤的黑色盔甲，手持他的战锤。]=],
		},
	},
	bonds = {
		{ id = "thrall", name = "萨尔", note = "他的大酋长继承人" },
		{ id = "gul-dan", name = "古尔丹", note = "他所鄙视的术士" },
		{ id = "anduin-lothar", name = "安度因·洛萨", note = "被他杀死的敌人" },
		{ id = "llane-wrynn", name = "莱恩·乌瑞恩", note = "他夺取了其城市的国王" },
		{ id = "grom-hellscream", name = "格罗姆·地狱咆哮", note = "一位酋长同伴" },
	},
})

Translate("zhCN", "grom-hellscream", {
	title = "格罗姆·地狱咆哮",
	subtitle = "战歌氏族酋长",
	allegiance = "部落 · 战歌氏族",
	aliases = { "格罗玛什", "格罗玛什·地狱咆哮" },
	sections = {
		{
			title = "概述",
			text = [=[格罗姆·地狱咆哮是战歌氏族的酋长，{link:orcs}兽人{/link}军阀中最凶猛的一位，也是{link:thrall}萨尔{/link}最真诚的朋友。他是第一个喝下恶魔{link:mannoroth}玛诺洛斯{/link}之血的兽人，从而把他的族人与{link:burning-legion}燃烧军团{/link}捆绑在一起。他也是那个以自己的生命为代价打破这一束缚的兽人。]=],
		},
		{
			title = "意义",
			text = [=[{link:orcs}兽人{/link}的诅咒始于格罗姆，也终于格罗姆。他在{link:ashenvale}灰谷{/link}的死让兽人摆脱了恶魔之血，今天的{link:horde}部落{/link}的自由归功于他最后的奋战。]=],
		},
		{
			title = "血之诅咒",
			text = [=[在{red:draenor}德拉诺{/red}，术士{link:gul-dan}古尔丹{/link}召集各氏族的酋长，献上了一杯{link:mannoroth}玛诺洛斯{/link}之血。格罗姆第一个喝下，其他人随后跟着喝了。这血让{link:orcs}兽人{/link}充满可怕的狂怒，并把他们束缚于军团的意志之下。当{link:horde}部落{/link}进军{link:azeroth}艾泽拉斯{/link}时，古尔丹设计把格罗姆和他的战歌氏族留在了德拉诺。他们完全错过了{link:second-war}第二次战争{/link}。战后，他们穿过{link:dark-portal}黑暗之门{/link}而来，为守住它而战，直到它被摧毁，他们也因此被困在了{link:humans}人类{/link}的土地上。]=],
		},
		{
			title = "昏睡",
			text = [=[多年来，战歌氏族隐居在{link:lordaeron}洛丹伦{/link}的荒野中。和所有{link:orcs}兽人{/link}一样，格罗姆因失去恶魔的狂怒而患病。但他以钢铁般的意志与昏睡抗争。当年轻的{link:thrall}萨尔{/link}找到他时，格罗姆在他身上看到了族人的希望。他与萨尔一同把兽人从{link:internment-camps}收容所{/link}中解放出来。{link:third-war}第三次战争{/link}前夕，他被{link:humans}人类{/link}俘虏，萨尔再次解救了他。]=],
		},
		{
			title = "卡利姆多",
			text = [=[{link:orcs}兽人{/link}向西航行至{link:kalimdor}卡利姆多{/link}。在那里，战歌氏族被派进{link:ashenvale}灰谷{/link}的森林伐木，与{link:night-elves}暗夜精灵{/link}发生了冲突。半神{link:cenarius}塞纳留斯{/link}前来保卫森林。格罗姆和他的战士们急于求胜，喝下了被{link:mannoroth}玛诺洛斯{/link}用自己的血污染的泉水。古老的诅咒卷土重来。在那股狂怒中，格罗姆杀死了塞纳留斯。{link:thrall}萨尔{/link}在{link:jaina-proudmoore}吉安娜·普罗德摩尔{/link}的帮助下抓住了他的朋友，并为他洗去了狂怒。]=],
		},
		{
			title = "事迹",
			text = [=[• 他是第一个喝下{link:mannoroth}玛诺洛斯{/link}之血的{link:orcs}兽人{/link}。
• {link:second-war}第二次战争{/link}后，他为守住{link:dark-portal}黑暗之门{/link}而与{link:alliance}联盟{/link}作战。
• 他在多年的隐居中抵抗着兽人的消沉。
• 他帮助{link:thrall}萨尔{/link}解放{link:internment-camps}收容所{/link}中的兽人。
• 他杀死了{link:cenarius}塞纳留斯{/link}，后来又杀死了玛诺洛斯。]=],
		},
		{
			title = "结局",
			text = [=[格罗姆和{link:thrall}萨尔{/link}一同前往{link:mannoroth}玛诺洛斯{/link}等候的峡谷。萨尔被恶魔的力量击倒。格罗姆独自冲锋，把战斧劈进玛诺洛斯的胸膛，杀死了他。恶魔之死让{link:orcs}兽人{/link}摆脱了血之诅咒。格罗姆因伤重死在萨尔的怀中。他的氏族仍以{link:horde}部落{/link}的名义砍伐{link:ashenvale}灰谷{/link}的树木，而{link:night-elves}暗夜精灵{/link}仍为每一棵树与他们争战。]=],
		},
	},
	bonds = {
		{ id = "thrall", name = "萨尔", note = "他的大酋长和朋友" },
		{ id = "gul-dan", name = "古尔丹", note = "给了他恶魔之血" },
		{ id = "orgrim-doomhammer", name = "奥格瑞姆·毁灭之锤", note = "一位酋长同伴" },
		{ id = "archimonde", name = "阿克蒙德", note = "被他杀死的那个恶魔的主人" },
		{ id = "jaina-proudmoore", name = "吉安娜·普罗德摩尔", note = "帮助解救了他" },
	},
})

Translate("zhCN", "gul-dan", {
	title = "古尔丹",
	subtitle = "兽人的背叛者",
	allegiance = "暗影议会 · 风暴掠夺者氏族",
	sections = {
		{
			title = "概述",
			text = [=[古尔丹是第一个{link:orcs}兽人{/link}术士，也是旧{link:horde}部落{/link}的缔造者。他曾是萨满祭司{link:ner-zhul}耐奥祖{/link}的学徒。他为了换取力量，把他的族人出卖给了{link:burning-legion}燃烧军团{/link}，毒害了他的种族和他的世界。他与{link:medivh}麦迪文{/link}一同打开了{link:dark-portal}黑暗之门{/link}，并领导着部落的幕后主宰——{link:shadow-council}暗影议会{/link}。最终，他背叛了部落本身。]=],
		},
		{
			title = "意义",
			text = [=[{link:orcs}兽人{/link}以及与他们交战的民族所遭受的许多苦难，都可以追溯到古尔丹的野心。他的{link:fel-magic}邪能魔法{/link}吸干了{red:draenor}德拉诺{/red}的生命。他的恶魔之血让兽人沦为自身狂怒的奴隶。他的背叛让{link:horde}部落{/link}输掉了{link:second-war}第二次战争{/link}。]=],
		},
		{
			title = "暗影议会",
			text = [=[在德拉诺，恶魔领主{link:kil-jaeden}基尔加丹{/link}在{link:orcs}兽人{/link}中寻找仆从。当{link:ner-zhul}耐奥祖{/link}开始怀疑这个恶魔时，基尔加丹转向了毫无疑虑的古尔丹。基尔加丹传授给他邪能巫术。古尔丹创立了{link:shadow-council}暗影议会{/link}，一个躲在傀儡大酋长黑手身后统治各氏族的术士集团。他向酋长们献上{link:mannoroth}玛诺洛斯{/link}之血，他们喝了下去。随后，一个来自另一个世界的声音找到了他。那是{link:medivh}麦迪文{/link}，他们一同打开了通往{link:azeroth}艾泽拉斯{/link}的{link:dark-portal}黑暗之门{/link}。]=],
		},
		{
			title = "战争",
			text = [=[{link:first-war}第一次战争{/link}结束时，古尔丹试图从{link:medivh}麦迪文{/link}垂死的心智中夺取{link:sargeras}萨格拉斯{/link}之墓的秘密。这一尝试让他陷入了长久的昏迷。在他沉睡期间，{link:orgrim-doomhammer}奥格瑞姆·毁灭之锤{/link}杀死了黑手，摧毁了{link:shadow-council}暗影议会{/link}的大部分成员。古尔丹醒来后，以提供新武器的承诺换回了自己的性命。他和他的术士们造出了{link:horde}部落{/link}的第一批死亡骑士。然而他的忠诚只是一副面具。当毁灭之锤围攻{link:lordaeron}洛丹伦{/link}都城时，古尔丹带着他的追随者扬帆而去，到海底寻找萨格拉斯之墓。]=],
		},
		{
			title = "事迹",
			text = [=[• 他创立了{link:shadow-council}暗影议会{/link}，并通过黑手统治{link:horde}部落{/link}。
• 他把{link:mannoroth}玛诺洛斯{/link}之血给了酋长们。
• 他与{link:medivh}麦迪文{/link}一同打开了{link:dark-portal}黑暗之门{/link}。
• 他造出了部落的第一批死亡骑士。
• 他在{link:lordaeron}洛丹伦{/link}都城的城门前抛弃了毁灭之锤。]=],
		},
		{
			title = "结局",
			text = [=[古尔丹从无尽之海的深处升起了{link:sargeras}萨格拉斯{/link}之墓，并走了进去，希望夺取一位神祇的力量。守卫墓穴的恶魔把他撕成了碎片。毁灭之锤派去惩罚他背叛的战士们屠杀了他的追随者。没有了他们，{link:horde}部落{/link}无法维持围攻，被打退而一败涂地。古尔丹的头骨在他死后留存下来，蕴含着自身的黑暗力量，直到在{link:third-war}第三次战争{/link}中被摧毁。]=],
		},
	},
	bonds = {
		{ id = "ner-zhul", name = "耐奥祖", note = "他的第一位导师" },
		{ id = "medivh", name = "麦迪文", note = "与他一同打开了黑暗之门" },
		{ id = "orgrim-doomhammer", name = "奥格瑞姆·毁灭之锤", note = "他背叛的大酋长" },
		{ id = "grom-hellscream", name = "格罗姆·地狱咆哮", note = "第一个喝下他所献之血的人" },
		{ id = "illidan-stormrage", name = "伊利丹·怒风", note = "夺取了他头骨的力量" },
	},
})

Translate("zhCN", "ner-zhul", {
	title = "耐奥祖",
	subtitle = "影月氏族的长老萨满祭司",
	allegiance = "影月氏族 · 天灾军团",
	sections = {
		{
			title = "概述",
			text = [=[耐奥祖是影月氏族的长老萨满祭司，也是{red:draenor}德拉诺{/red}{link:orcs}兽人{/link}中最受尊敬的精神领袖。恶魔领主{link:kil-jaeden}基尔加丹{/link}欺骗了他，利用他让兽人与德莱尼为敌。后来，耐奥祖为了逃离自己的世界，把它撕成了碎片。他被恶魔俘获，被变成了{red:lich-king}巫妖王{/red}，{link:scourge}天灾军团{/link}之主。]=],
		},
		{
			title = "意义",
			text = [=[耐奥祖两度带来毁灭。作为萨满祭司，他让族人的心向{link:burning-legion}燃烧军团{/link}敞开。作为巫妖王，他向{link:lordaeron}洛丹伦{/link}降下了亡灵瘟疫。{link:third-war}第三次战争{/link}和北方的死寂之地，既是别人的杰作，也同样是他的杰作。]=],
		},
		{
			title = "欺骗者",
			text = [=[在德拉诺的古老岁月里，{link:orcs}兽人{/link}以猎人和萨满祭司组成的氏族为生。耐奥祖在他们中间代表众灵发言。后来，{link:kil-jaeden}基尔加丹{/link}伪装成祖先之灵来到他面前，低声说爱好和平的德莱尼正在密谋对付兽人。耐奥祖相信了他，带领族人走向战争。直到后来他才看清真相，当他拒绝再往前走时，基尔加丹转而找上了他的学徒{link:gul-dan}古尔丹{/link}。耐奥祖被弃置一旁，在{link:horde}部落{/link}进军{link:azeroth}艾泽拉斯{/link}时于羞辱中度日。]=],
		},
		{
			title = "碎裂",
			text = [=[{link:second-war}第二次战争{/link}后，留在德拉诺的{link:orcs}兽人{/link}聚集在这位老萨满祭司周围。他重新打开了{link:dark-portal}黑暗之门{/link}，派战士去{link:azeroth}艾泽拉斯{/link}窃取强大的圣物，意图为他的族人打开通往新世界的传送门。{link:alliance}联盟{/link}派出一支远征军穿过黑暗之门去阻止他。耐奥祖仍然打开了他的传送门。这些能量把德拉诺撕裂了，他带着追随者从一道裂隙中逃走。]=],
		},
		{
			title = "事迹",
			text = [=[• 他作为{link:orcs}兽人{/link}最伟大的萨满祭司领导他们。
• 在{link:kil-jaeden}基尔加丹{/link}的欺骗下，他率领各氏族与德莱尼为敌。
• {link:second-war}第二次战争{/link}后，他重新打开了{link:dark-portal}黑暗之门{/link}。
• 他用他的传送门粉碎了德拉诺。
• 作为巫妖王，他造出了{link:scourge}天灾军团{/link}，向{link:lordaeron}洛丹伦{/link}释放了瘟疫。]=],
		},
		{
			title = "结局",
			text = [=[{link:kil-jaeden}基尔加丹{/link}在裂隙的另一边等着他。恶魔把萨满祭司的血肉从身上剥离，把他的灵魂禁锢在一套盔甲和一顶头盔中。他把耐奥祖封在一块寒冰里，扔向了{link:azeroth}艾泽拉斯{/link}。它落在{red:northrend}诺森德{/red}的冰冠冰川上，他在那里成了巫妖王。他从冰封王座上造出了{link:scourge}天灾军团{/link}。他召{link:kel-thuzad}克尔苏加德{/link}为他效力，把瘟疫送往南方。最后，他通过符文剑{red:frostmourne}霜之哀伤{/red}夺取了王子{link:arthas-menethil}阿尔萨斯·米奈希尔{/link}。当他的力量衰退时，他把阿尔萨斯召到冰冠冰川，王子戴上了他的头盔。耐奥祖和阿尔萨斯如今合而为一，巫妖王统治着北方。]=],
		},
	},
	bonds = {
		{ id = "gul-dan", name = "古尔丹", note = "他的学徒，也是篡夺他地位的人" },
		{ id = "arthas-menethil", name = "阿尔萨斯·米奈希尔", note = "他夺取并与之结合的王子" },
		{ id = "kel-thuzad", name = "克尔苏加德", note = "他的仆从" },
		{ id = "grom-hellscream", name = "格罗姆·地狱咆哮", note = "他的部落中的酋长" },
	},
})

Translate("zhCN", "archimonde", {
	title = "阿克蒙德",
	subtitle = "污染者",
	allegiance = "燃烧军团",
	sections = {
		{
			title = "概述",
			text = [=[{link:defilers}污染者{/link}阿克蒙德是{link:burning-legion}燃烧军团{/link}的大领主之一，地位仅次于军团的黑暗主宰{link:sargeras}萨格拉斯{/link}。他曾是艾瑞达人的领袖之一，那是另一个世界上的一个骄傲民族，直到萨格拉斯向他们许以力量，而他接受了。他在无数世界上进行着军团的战争。在{link:azeroth}艾泽拉斯{/link}，他比之前任何一个恶魔都更接近吞噬这个世界，最终死在了世界之树脚下。]=],
		},
		{
			title = "意义",
			text = [=[阿克蒙德在{link:third-war}第三次战争{/link}中的入侵，是自{link:war-of-the-ancients}上古战争{/link}以来这个世界所经历的最大规模的恶魔进攻。他在{link:mount-hyjal}海加尔山{/link}的败亡，促成了{link:orcs}兽人{/link}、{link:humans}人类{/link}和{link:night-elves}暗夜精灵{/link}之间一份不安的和平，这份和平从此塑造了{link:kalimdor}卡利姆多{/link}。]=],
		},
		{
			title = "艾瑞达人",
			text = [=[很久以前，艾瑞达人由三位领袖统治：阿克蒙德、{link:kil-jaeden}基尔加丹{/link}和维伦。{link:sargeras}萨格拉斯{/link}带着知识与力量的许诺来到他们面前。阿克蒙德和基尔加丹接受了，被扭曲成了恶魔。维伦拒绝了，带着他的追随者逃走。阿克蒙德成为萨格拉斯最得力的副官之一。一万年前的{link:war-of-the-ancients}上古战争{/link}中，军团通过{link:well-of-eternity}永恒之井{/link}来到{link:azeroth}艾泽拉斯{/link}。永恒之井被摧毁后，军团被击退。]=],
		},
		{
			title = "第三次战争",
			text = [=[许多个时代之后，军团卷土重来。在{link:scourge}天灾军团{/link}蹂躏了{link:lordaeron}洛丹伦{/link}之后，巫妖{link:kel-thuzad}克尔苏加德{/link}用{link:medivh}麦迪文{/link}的魔法书把阿克蒙德召唤到了{link:dalaran}达拉然{/link}城中。恶魔领主以他力量的一击便摧毁了这座{link:city-of-dalaran}法师之城{/link}。随后他率领军团前往{link:kalimdor}卡利姆多{/link}，{link:well-of-eternity}永恒之井{/link}最后的井水就在那里的世界之树{link:nordrassil}诺达希尔{/link}之下。他打算吸干它的力量，吞噬这个世界。]=],
		},
		{
			title = "事迹",
			text = [=[• 他接受了{link:sargeras}萨格拉斯{/link}的许诺，成为军团的领主。
• 他在{link:war-of-the-ancients}上古战争{/link}中向{link:azeroth}艾泽拉斯{/link}发动战争。
• 他被{link:kel-thuzad}克尔苏加德{/link}召唤到{link:dalaran}达拉然{/link}，并摧毁了它。
• 他向{link:mount-hyjal}海加尔山{/link}进军，要吸干{link:nordrassil}诺达希尔{/link}的力量。]=],
		},
		{
			title = "结局",
			text = [=[在{link:battle-of-mount-hyjal}海加尔山之战{/link}中，{link:thrall}萨尔{/link}的{link:orcs}兽人{/link}、{link:jaina-proudmoore}吉安娜·普罗德摩尔{/link}的{link:humans}人类{/link}，以及{link:tyrande-whisperwind}泰兰德·语风{/link}和{link:malfurion-stormrage}玛法里奥·怒风{/link}的{link:night-elves}暗夜精灵{/link}，尽可能长久地守住了山坡。阿克蒙德终于登上了世界之树。玛法里奥吹响了{link:cenarius}塞纳留斯{/link}之角，无数先祖之灵蜂拥扑向恶魔领主，在一场巨大的爆炸中将他消灭。{link:nordrassil}诺达希尔{/link}的力量耗尽了，暗夜精灵失去了永生。然而军团的入侵被粉碎了。它的恶魔仍徘徊在{link:felwood}费伍德森林{/link}被腐化的{link:moonglade}林地{/link}中，它的阴影也尚未离开这个世界。]=],
		},
	},
	bonds = {
		{ id = "kel-thuzad", name = "克尔苏加德", note = "把他召唤到艾泽拉斯" },
		{ id = "malfurion-stormrage", name = "玛法里奥·怒风", note = "促成了他的毁灭" },
		{ id = "illidan-stormrage", name = "伊利丹·怒风", note = "第三次战争中的敌人" },
		{ id = "queen-azshara", name = "艾萨拉女王", note = "在古时为军团打开了道路" },
		{ id = "grom-hellscream", name = "格罗姆·地狱咆哮", note = "杀死了他的仆从玛诺洛斯" },
	},
})

Translate("zhCN", "illidan-stormrage", {
	title = "伊利丹·怒风",
	subtitle = "背叛者",
	allegiance = "不明（曾属卡多雷抵抗军）",
	aliases = { "伊利丹", "背叛者" },
	sections = {
		{
			title = "概述",
			text = [=[伊利丹·怒风是远古世界的一位{link:night-elves}暗夜精灵{/link}术士，{link:malfurion-stormrage}玛法里奥·怒风{/link}的孪生兄弟，也是争夺{link:tyrande-whisperwind}泰兰德·语风{/link}之爱的竞争者。他与{link:burning-legion}燃烧军团{/link}作战，也曾为它效力。他被囚禁了一万年，在{link:third-war}第三次战争{/link}中获释。有人称他为英雄，更多的人称他为叛徒。他自己的族人称他为背叛者。]=],
		},
		{
			title = "意义",
			text = [=[伊利丹的选择既拯救过这个世界，也同样威胁过它。在远古时代，他把{link:well-of-eternity}永恒之井{/link}的井水带到了{link:mount-hyjal}海加尔山{/link}，那些井水至今仍在{link:nordrassil}诺达希尔{/link}之下。在{link:third-war}第三次战争{/link}中，他杀死了军团的一位领主，并把它的力量据为己有。]=],
		},
		{
			title = "上古战争",
			text = [=[伊利丹生来便有一双琥珀色的眼睛，据说这是预示伟大的标志。他被{link:arcane-magic}奥术魔法{/link}所吸引，正如他的兄弟被{link:cenarius}塞纳留斯{/link}之道所吸引。在{link:war-of-the-ancients}上古战争{/link}中，他与{link:night-elves}暗夜精灵{/link}并肩对抗{link:queen-azshara}艾萨拉女王{/link}和她的恶魔盟友。然而他嫉妒自己的兄弟，又渴求力量，最终投向了{link:sargeras}萨格拉斯{/link}本人。恶魔领主烧掉了他的双眼，赐予他一种新的视觉。{link:well-of-eternity}永恒之井{/link}被摧毁时，伊利丹把偷来的几瓶井水倒进了{link:mount-hyjal}海加尔山{/link}顶的一座湖中，创造了一口新的永恒之井。{link:malfurion-stormrage}玛法里奥{/link}认定这是一桩罪行。他把自己的兄弟锁在地下，由{link:the-night-watch}守望者{/link}玛维·影歌看守。]=],
		},
		{
			title = "第三次战争",
			text = [=[一万年后，{link:scourge}天灾军团{/link}和{link:burning-legion}燃烧军团{/link}来到了{link:kalimdor}卡利姆多{/link}。{link:tyrande-whisperwind}泰兰德{/link}违背族人的律法，释放了伊利丹以求相助。在如今名为{link:felwood}费伍德森林{/link}的森林中，他吞噬了{link:gul-dan}古尔丹{/link}之颅，化为恶魔之形，杀死了恐惧魔王{link:tichondrius}提克迪奥斯{/link}。{link:malfurion-stormrage}玛法里奥{/link}把他逐出了{link:night-elves}暗夜精灵{/link}的森林。]=],
		},
		{
			title = "事迹",
			text = [=[• 他在{link:war-of-the-ancients}上古战争{/link}中对抗{link:azshara}艾萨拉{/link}。
• 他在{link:mount-hyjal}海加尔山{/link}顶创造了一口新的{link:well-of-eternity}永恒之井{/link}。
• 他吞噬了{link:skull-of-gul-dan}古尔丹之颅{/link}，杀死了{link:tichondrius}提克迪奥斯{/link}。
• {link:third-war}第三次战争{/link}后，他召唤深海的{link:naga}纳迦{/link}为他效力。]=],
		},
		{
			title = "结局",
			text = [=[被放逐后，伊利丹召集了{link:naga}纳迦{/link}，到海底寻找{link:sargeras}萨格拉斯{/link}之墓。玛维追捕他，他的兄弟和{link:tyrande-whisperwind}泰兰德{/link}也追捕他，而他从他们所有人手中逃脱。后来，他进军{red:northrend}诺森德{/red}去打击{red:lich-king}巫妖王{/red}。在冰冠冰川，他与{link:arthas-menethil}阿尔萨斯·米奈希尔{/link}交战并被击败。他带着幸存的追随者逃走了。此后他去了哪里，诸王国的任何编年史都说不清。]=],
		},
	},
	bonds = {
		{ id = "malfurion-stormrage", name = "玛法里奥·怒风", note = "他的孪生兄弟" },
		{ id = "tyrande-whisperwind", name = "泰兰德·语风", note = "他失去的爱人" },
		{ id = "queen-azshara", name = "艾萨拉女王", note = "往昔的敌人" },
		{ id = "arthas-menethil", name = "阿尔萨斯·米奈希尔", note = "在冰冠冰川击败了他" },
		{ id = "gul-dan", name = "古尔丹", note = "他吞噬了其头颅" },
	},
})

Translate("zhCN", "malfurion-stormrage", {
	title = "玛法里奥·怒风",
	subtitle = "第一位德鲁伊",
	allegiance = "暗夜精灵 · 塞纳里奥议会",
	aliases = { "玛法里奥" },
	sections = {
		{
			title = "概述",
			text = [=[玛法里奥·怒风是第一位{link:night-elves}暗夜精灵{/link}德鲁伊，半神{link:cenarius}塞纳留斯{/link}的学生，{link:illidan-stormrage}伊利丹·怒风{/link}的孪生兄弟。他在{link:war-of-the-ancients}上古战争{/link}中领导了对{link:burning-legion}燃烧军团{/link}的战斗，又在{link:third-war}第三次战争{/link}中再度领导。他是{link:tyrande-whisperwind}泰兰德·语风{/link}的爱人。他如今沉睡在{link:emerald-dream}翡翠梦境{/link}中，他的族人在等待他醒来。]=],
		},
		{
			title = "意义",
			text = [=[玛法里奥两次拯救了这个世界。在远古时代，他摧毁了{link:well-of-eternity}永恒之井{/link}，关上了通往军团的大门。一万年后，他在世界之树脚下消灭了{link:archimonde}阿克蒙德{/link}。各地的德鲁伊都走在他最先走过的道路上。]=],
		},
		{
			title = "上古战争",
			text = [=[他的兄弟研习奥术时，玛法里奥却被生机勃勃的世界所吸引。{link:cenarius}塞纳留斯{/link}收他为学生，教他塑造自然的力量。当{link:queen-azshara}艾萨拉女王{/link}和她的上层精灵把军团引入这个世界时，玛法里奥加入了抵抗军。他看出，只有摧毁{link:well-of-eternity}永恒之井{/link}本身，才能阻止军团。他对永恒之井的攻击引发了{link:great-sundering}大分裂{/link}，大地破碎，女王的都城被海水吞没。当{link:illidan-stormrage}伊利丹{/link}在{link:mount-hyjal}海加尔山{/link}创造了一口新的永恒之井时，玛法里奥把他囚禁了起来。在巨龙的帮助下，幸存者们在新的永恒之井上种下了{link:nordrassil}诺达希尔{/link}。随后，玛法里奥和他的德鲁伊们在{link:emerald-dream}翡翠梦境{/link}中陷入了长眠。]=],
		},
		{
			title = "第三次战争",
			text = [=[当军团卷土重来时，{link:tyrande-whisperwind}泰兰德{/link}唤醒了德鲁伊。玛法里奥带领他们回到世间，帮助守住{link:ashenvale}灰谷{/link}的森林，抵御恶魔。泰兰德违背他的意愿释放了{link:illidan-stormrage}伊利丹{/link}，而他赶到时已来不及阻止兄弟夺取恶魔的力量。他放逐了伊利丹，回去保卫{link:mount-hyjal}海加尔山{/link}。在那里，他与{link:thrall}萨尔{/link}的{link:orcs}兽人{/link}和{link:jaina-proudmoore}吉安娜·普罗德摩尔{/link}的{link:humans}人类{/link}并肩作战。当{link:archimonde}阿克蒙德{/link}抵达{link:nordrassil}诺达希尔{/link}时，玛法里奥吹响了{link:cenarius}塞纳留斯{/link}之角。先祖之灵消灭了恶魔领主，世界得救了。]=],
		},
		{
			title = "事迹",
			text = [=[• 他向{link:cenarius}塞纳留斯{/link}学习自然之道，成为第一位德鲁伊。
• 他摧毁了{link:well-of-eternity}永恒之井{/link}，结束了{link:war-of-the-ancients}上古战争{/link}。
• 他把自己的兄弟囚禁在地下。
• 他在{link:third-war}第三次战争{/link}中率领德鲁伊对抗军团。
• 他在{link:battle-of-mount-hyjal}海加尔山之战{/link}中消灭了{link:archimonde}阿克蒙德{/link}。]=],
		},
		{
			title = "结局",
			text = [=[战后，玛法里奥渡海追捕{link:illidan-stormrage}伊利丹{/link}，随后放他离去。他回到了{link:emerald-dream}翡翠梦境{/link}，从此再未醒来。在他缺席期间，大德鲁伊{link:fandral-staghelm}范达尔·鹿盔{/link}领导着{link:darnassus}达纳苏斯{/link}的德鲁伊，{link:night-elves}暗夜精灵{/link}种下了一棵新的世界之树{link:teldrassil}泰达希尔{/link}。{link:tyrande-whisperwind}泰兰德{/link}统治着族人，并在等待。]=],
		},
	},
	bonds = {
		{ id = "illidan-stormrage", name = "伊利丹·怒风", note = "他的孪生兄弟" },
		{ id = "tyrande-whisperwind", name = "泰兰德·语风", note = "他的爱人" },
		{ id = "archimonde", name = "阿克蒙德", note = "被他消灭的恶魔" },
		{ id = "queen-azshara", name = "艾萨拉女王", note = "他所对抗的女王" },
		{ id = "fandral-staghelm", name = "范达尔·鹿盔", note = "代替他领导德鲁伊" },
	},
})

Translate("zhCN", "queen-azshara", {
	title = "艾萨拉女王",
	subtitle = "上层精灵的女王",
	allegiance = "上层精灵 · 纳迦",
	sections = {
		{
			title = "概述",
			text = [=[艾萨拉女王在古代{link:night-elves}暗夜精灵{/link}帝国最辉煌的时期统治着它。她是她的族人中最美丽也最强大的人，族人们崇拜她。她在{link:well-of-eternity}永恒之井{/link}旁的辛艾萨莉宫殿中，带领上层精灵研习{link:arcane-magic}奥术魔法{/link}。出于骄傲，她向{link:burning-legion}燃烧军团{/link}敞开了这个世界，她的帝国也沉入了海底。]=],
		},
		{
			title = "意义",
			text = [=[{link:azshara}艾萨拉{/link}的背叛引发了{link:war-of-the-ancients}上古战争{/link}，并以{link:great-sundering}大分裂{/link}告终。{link:kalimdor}卡利姆多{/link}和{link:eastern-kingdoms}东部王国{/link}破碎的形状便是她的遗产。如今从海浪中崛起的{link:naga}纳迦{/link}，或许也是。]=],
		},
		{
			title = "上层精灵的女王",
			text = [=[{link:azshara}艾萨拉{/link}的族人用她的名字命名城市和山脉。上层精灵是她宫廷中的贵族阶层，以祭司和术士的身份侍奉她。在她的统治下，他们越来越深地汲取{link:well-of-eternity}永恒之井{/link}的力量。他们的法术延伸到了世界之外，引起了{link:sargeras}萨格拉斯{/link}的注意。恶魔领主向女王低语，而她听从了。她开始相信，这个世界应当清除一切低等民族，而萨格拉斯会让这一切成真。]=],
		},
		{
			title = "上古战争",
			text = [=[{link:azshara}艾萨拉{/link}和她的上层精灵在{link:well-of-eternity}永恒之井{/link}中打开了一道传送门，军团的恶魔蜂拥而入。她的谋士{link:shadow-priest-sarvis}萨维斯{/link}在这件事上为她效力。仍然保有自由的{link:night-elves}暗夜精灵{/link}在{link:malfurion-stormrage}玛法里奥·怒风{/link}、{link:tyrande-whisperwind}泰兰德·语风{/link}和库塔洛斯·拉文凯斯领主的带领下起来反抗他们的女王。战争激烈进行时，上层精灵努力要把{link:sargeras}萨格拉斯{/link}本人带进这个世界。直到永恒之井被摧毁，他们才被阻止。它的崩塌撕裂了大地，海水涌入，淹没了辛艾萨莉。]=],
		},
		{
			title = "事迹",
			text = [=[• 她在{link:night-elves}暗夜精灵{/link}最强盛的时期统治着他们。
• 她带领上层精灵运用{link:well-of-eternity}永恒之井{/link}的力量。
• 她为{link:burning-legion}燃烧军团{/link}打开了进入{link:azeroth}艾泽拉斯{/link}的道路。
• 她试图把{link:sargeras}萨格拉斯{/link}本人带进这个世界。]=],
		},
		{
			title = "结局",
			text = [=[{link:well-of-eternity}永恒之井{/link}崩塌时，艾萨拉和她的上层精灵消失在海浪之下。{link:night-elves}暗夜精灵{/link}的传说称，他们并没有死，而是发生了变化，那些蛇形的{link:naga}纳迦{/link}就是他们变成的模样。如今纳迦已回到海岸，袭击{link:kalimdor}卡利姆多{/link}和其他土地的海岸。他们中有些人谈起他们古老的女王时，仿佛她仍然活着。在以她命名的土地{link:azshara}艾萨拉{/link}上，只剩下她帝国的废墟。]=],
		},
		{ title = "无从记载", text = "没有任何凡人的记录说明{link:azshara}艾萨拉{/link}是否仍活在海底，或她变成了什么。" },
	},
	bonds = {
		{ id = "malfurion-stormrage", name = "玛法里奥·怒风", note = "领导了反抗她的起义" },
		{ id = "illidan-stormrage", name = "伊利丹·怒风", note = "与她的宫廷作战" },
		{ id = "archimonde", name = "阿克蒙德", note = "她所侍奉的军团领主" },
		{ id = "tyrande-whisperwind", name = "泰兰德·语风", note = "领导了反抗她的起义" },
	},
})

Translate("zhCN", "deathwing", {
	title = "死亡之翼",
	subtitle = "毁灭者",
	allegiance = "黑龙军团",
	aliases = { "耐萨里奥" },
	sections = {
		{
			title = "概述",
			text = [=[死亡之翼曾是黑龙军团的守护巨龙——大地守护者耐萨里奥。他肩负着守护世界深处的职责。疯狂攫住了他，他在{link:war-of-the-ancients}上古战争{/link}中背叛了其他龙族。从那以后，他一直在谋害{link:azeroth}艾泽拉斯{/link}的每一个民族。他的名字对巨龙和凡人来说都意味着毁灭。]=],
		},
		{
			title = "意义",
			text = [=[死亡之翼的背叛几乎毁灭了各个龙族。他在{link:second-war}第二次战争{/link}中的插手让{link:horde}部落{/link}得到了巨龙。他的黑龙子嗣至今仍盘踞在{link:blackrock-mountain}黑石山{/link}和世界上其他黑暗之地。]=],
		},
		{
			title = "大地守护者",
			text = [=[在远古时代，五头伟大的巨龙被选为守护巨龙，守护这个世界。耐萨里奥被赋予了掌管大地及其深处的权力。有什么东西从岩石深处向他低语，久而久之，他的心智发生了扭曲。在{link:war-of-the-ancients}上古战争{/link}中，他铸造了一个巨大的{link:ginro-hearthkindle}金{/link}色圆盘——巨龙之魂。他说服其他守护巨龙把一部分力量注入其中，告诉他们这能击退{link:burning-legion}燃烧军团{/link}。然而他却用它来对付他们。这件神器的力量是如此强大，以至于他的身体开始撕裂，人们只好在他的皮上固定金属板来让他的身躯保持完整。他逃走了，巨龙之魂也失落了。]=],
		},
		{
			title = "第二次战争",
			text = [=[死亡之翼长久以来一直伪装成{link:humans}人类{/link}行走于凡人之间，以一位贵族的身份周旋于诸王的宫廷。史书说，他所到之处无不挑起纷争。在{link:second-war}第二次战争{/link}中，巨龙之魂落入了{link:dragonmaw-clan}龙喉氏族兽人{/link}之手。他们用它俘获了红龙的守护巨龙{link:alexstrasza}阿莱克丝塔萨{/link}，把她囚禁在{link:grim-batol}格瑞姆巴托{/link}之下。她的幼龙被养大，成为{link:horde}部落{/link}的战争坐骑。]=],
		},
		{
			title = "事迹",
			text = [=[• 他在{link:war-of-the-ancients}上古战争{/link}中用巨龙之魂背叛了守护巨龙。
• 他秘密地周旋于{link:humans}人类{/link}的宫廷之间。
• 他让巨龙之魂落入了{link:dragonmaw-clan}龙喉氏族{/link}之手。
• 他试图从{link:grim-batol}格瑞姆巴托{/link}窃取红龙军团的龙蛋。]=],
		},
		{
			title = "结局",
			text = [=[{link:second-war}第二次战争{/link}后，{link:dragonmaw-clan}龙喉氏族{/link}仍把{link:alexstrasza}阿莱克丝塔萨{/link}囚禁在{link:grim-batol}格瑞姆巴托{/link}。死亡之翼前来夺取她的龙蛋，企图重建自己的龙族。一小队英雄和巨龙解救了红龙女王，巨龙之魂被摧毁了。死亡之翼在狂怒中被赶走。他去了哪里，无人知晓。{link:wetlands}湿地{/link}的格瑞姆巴托山至今仍为{link:dwarves}矮人{/link}所回避。他的子女和他的黑龙军团仍在世间活动。]=],
		},
	},
	bonds = {
		{ id = "alexstrasza", name = "阿莱克丝塔萨", note = "他协助奴役的守护巨龙" },
		{ id = "orgrim-doomhammer", name = "奥格瑞姆·毁灭之锤", note = "利用了他的“礼物”的部落大酋长" },
		{ id = "queen-azshara", name = "艾萨拉女王", note = "他声称要对抗的军团的盟友" },
	},
})

Translate("zhCN", "kel-thuzad", {
	title = "克尔苏加德",
	subtitle = "诅咒教派的创始人",
	allegiance = "天灾军团 · 诅咒教派（曾属肯瑞托）",
	sections = {
		{
			title = "概述",
			text = [=[克尔苏加德曾是{link:dalaran}达拉然{/link}的一位大法师，{link:kirin-tor}肯瑞托{/link}统治{link:shadow-council}议会{/link}的成员。他转向了被禁止的死灵术，宣誓效忠{red:lich-king}巫妖王{/red}，创立了{link:cult-of-the-damned}诅咒教派{/link}。他散播了毁灭{link:lordaeron}洛丹伦{/link}的瘟疫。他被王子{link:arthas-menethil}阿尔萨斯·米奈希尔{/link}杀死后，又作为巫妖复活。他如今以主人的名义在洛丹伦指挥着{link:scourge}天灾军团{/link}。]=],
		},
		{
			title = "意义",
			text = [=[没有克尔苏加德，亡灵瘟疫也许永远不会降临到{link:lordaeron}洛丹伦{/link}的人民身上。他是巫妖王在生者之中的代言人，并为{link:burning-legion}燃烧军团{/link}重返{link:azeroth}艾泽拉斯{/link}打开了道路。]=],
		},
		{
			title = "大法师",
			text = [=[克尔苏加德是{link:dalaran}达拉然{/link}最伟大的法师之一，但他认为他的法师同僚们在研究上过于胆怯。他开始钻研死灵术这门黑暗技艺。{link:shadow-council}议会{/link}禁止此事后，他并没有停止。一个声音从{red:northrend}诺森德{/red}呼唤他。他做出了回应，前往冰封的北方，宣誓效忠巫妖王。他的主人许诺给他永恒的生命。]=],
		},
		{
			title = "诅咒教派",
			text = [=[克尔苏加德回到{link:lordaeron}洛丹伦{/link}，向贫苦和疲惫的人们讲述一个人人平等、无人死亡的新社会。成千上万的人加入了他的{link:cult-of-the-damned}诅咒教派{/link}。他通过他们，用一种把生者变成亡灵的瘟疫污染了北方粮仓的粮食。当{link:arthas-menethil}阿尔萨斯{/link}北上对抗瘟疫时，他在{link:ruins-of-andorhal}安多哈尔{/link}找到并杀死了克尔苏加德。然而这个死灵法师的灵魂留了下来，在他倒下时向王子低语。]=],
		},
		{
			title = "事迹",
			text = [=[• 他违抗{link:kirin-tor}肯瑞托{/link}，研习死灵术。
• 他在诺森德宣誓效忠巫妖王。
• 他创立了{link:cult-of-the-damned}诅咒教派{/link}。
• 他通过{link:lordaeron}洛丹伦{/link}的粮食散播亡灵瘟疫。
• 他把{link:archimonde}阿克蒙德{/link}召唤到了{link:dalaran}达拉然{/link}。]=],
		},
		{
			title = "结局",
			text = [=[当{link:arthas-menethil}阿尔萨斯{/link}成为巫妖王的仆从后，他把这个死灵法师的遗骸带到了{link:quel-thalas}奎尔萨拉斯{/link}。在那里，在太阳之井的水中，克尔苏加德作为巫妖重生。他用{link:medivh}麦迪文{/link}的魔法书把{link:archimonde}阿克蒙德{/link}召唤到{link:dalaran}达拉然{/link}，恶魔领主把这座城市化为废墟。当阿尔萨斯回到诺森德时，克尔苏加德留了下来，在{link:lordaeron}洛丹伦{/link}统治{link:scourge}天灾军团{/link}。他至今仍是如此。巨大的浮空城{red:naxxramas}纳克萨玛斯{/red}漂浮在瘟疫之地上空，他的信徒在{link:caer-darrow}凯尔达隆{/link}的古堡中开办着他们的黑暗学院。]=],
		},
	},
	bonds = {
		{ id = "arthas-menethil", name = "阿尔萨斯·米奈希尔", note = "先是杀死他的人，后成为他的主人" },
		{ id = "ner-zhul", name = "耐奥祖", note = "他宣誓效忠的巫妖王" },
		{ id = "archimonde", name = "阿克蒙德", note = "他召唤的恶魔" },
		{ id = "terenas-menethil", name = "泰瑞纳斯·米奈希尔", note = "其骨灰为他的遗骨腾出了位置" },
	},
})

Translate("zhCN", "jaina-proudmoore", {
	title = "吉安娜·普罗德摩尔",
	subtitle = "塞拉摩的统治者",
	found = "尘泥沼泽，塞拉摩岛，塞拉摩堡垒",
	hint = "到塞拉摩岛上城堡的高塔中寻找塞拉摩的女士。",
	allegiance = "塞拉摩 · 联盟 · 肯瑞托",
	aliases = { "吉安娜", "吉安娜·普罗德摩尔女士", "普罗德摩尔女士" },
	sections = {
		{
			title = "概述",
			text = [=[吉安娜·普罗德摩尔女士统治着{link:theramore-isle}塞拉摩{/link}，那是{link:alliance}联盟{/link}在{link:kalimdor}卡利姆多{/link}东海岸的岛屿要塞。她是{link:kul-tiras}库尔提拉斯{/link}的海军上将{link:daelin-proudmoore}戴林·普罗德摩尔{/link}之女，也是一位在{link:dalaran}达拉然{/link}受过{link:kirin-tor}肯瑞托{/link}训练的女术士。在瘟疫年代，她曾与王子{link:arthas-menethil}阿尔萨斯·米奈希尔{/link}同行，并在他堕落之前与他分道扬镳。她带领北方的幸存者渡海而来，并与{link:horde}部落{/link}缔结了一份在她之前无人认为可能的和平。]=],
		},
		{
			title = "意义",
			text = [=[吉安娜是旧日仇敌之间的桥梁。她在{link:battle-of-mount-hyjal}海加尔山之战{/link}中与{link:thrall}萨尔{/link}并肩作战，至今仍对他信守承诺。这份和平让她失去了父亲。它是脆弱的，双方都有许多人希望看到它破裂。]=],
		},
		{
			title = "瘟疫",
			text = [=[年轻时，吉安娜在{link:dalaran}达拉然{/link}师从大法师{link:brother-anton}安东{/link}尼达斯学习魔法，展现出罕见的天赋。当一场奇怪的瘟疫在{link:lordaeron}洛丹伦{/link}北部的农田中蔓延时，她与{link:arthas-menethil}阿尔萨斯王子{/link}一同去寻找它的源头。他们一起揭露了{link:cult-of-the-damned}诅咒教派{/link}和被污染的粮食。在斯坦索姆，阿尔萨斯下令在城中百姓变成亡灵之前将他们杀死。吉安娜不愿参与，在那里离开了他。{link:culling-of-stratholme}斯坦索姆的净化{/link}在没有她的情况下进行了。]=],
		},
		{
			title = "西行",
			text = [=[一位神秘的先知敦促东方的领袖们向西渡海。别人不听，吉安娜却听从了他，带领{link:lordaeron}洛丹伦{/link}的幸存者来到了{link:kalimdor}卡利姆多{/link}。在那里，她遇到了{link:thrall}萨尔{/link}和他的{link:orcs}兽人{/link}，她的族人的宿敌。先知让他们联合起来对抗一个更强大的敌人，在{link:mount-hyjal}海加尔山{/link}，{link:humans}人类{/link}、兽人和{link:night-elves}暗夜精灵{/link}并肩作战，直到{link:archimonde}阿克蒙德{/link}被消灭。]=],
		},
		{
			title = "事迹",
			text = [=[• 她在{link:dalaran}达拉然{/link}的{link:kirin-tor}肯瑞托{/link}中研习魔法。
• 她与{link:arthas-menethil}阿尔萨斯{/link}一同追查瘟疫，并拒绝参与{link:culling-of-stratholme}斯坦索姆的净化{/link}。
• 她带领{link:lordaeron}洛丹伦{/link}的幸存者西行至{link:kalimdor}卡利姆多{/link}。
• 她在{link:mount-hyjal}海加尔山{/link}与{link:thrall}萨尔{/link}和{link:night-elves}暗夜精灵{/link}并肩作战。
• 她建立了{link:theramore-isle}塞拉摩{/link}，并与{link:horde}部落{/link}缔结了和平。]=],
		},
		{
			title = "塞拉摩",
			text = [=[战后，吉安娜在{link:dustwallow-marsh}尘泥沼泽{/link}外海的一座岛屿上建起了{link:theramore-isle}塞拉摩{/link}。随后，她的父亲率领一支庞大的舰队来到了{link:kalimdor}卡利姆多{/link}。{link:daelin-proudmoore}戴林{/link}不接受与{link:orcs}兽人{/link}的和平，向他们开战。吉安娜无法说服他停手。她不愿让他摧毁这份和平，于是在{link:horde}部落{/link}自卫时袖手旁观。戴林在塞拉摩城墙前的战斗中阵亡。他的女儿为他悲伤，而追随他的水手们没有原谅她。]=],
		},
		{
			title = "当今之世",
			text = [=[吉安娜在{link:theramore-isle}塞拉摩{/link}的城堡中统治着这座城市。这座城市是失落北方之民的避风港，也是{link:alliance}联盟{/link}进入{link:kalimdor}卡利姆多{/link}的门户。她尽力维护着与{link:thrall}萨尔{/link}的和平，而双方的士兵仍在荒野中冲突不断。]=],
		},
	},
	chapters = {
		{
			title = "失踪的外交官",
			hint = "循着失踪外交官的线索前往塞拉摩。",
			text = [=[一位被劫持的使节留下的线索，从{link:stormwind-city}暴风城{/link}通往{link:menethil-harbor}米奈希尔港{/link}，又从那里渡海通往{link:dustwallow-marsh}尘泥沼泽{/link}。线索的尽头是{link:private-hendel}亨德尔下士{/link}，一名把自己出卖给{link:defias-brotherhood}迪菲亚兄弟会{/link}的{link:theramore-isle}塞拉摩{/link}士兵。他被揭穿时拔出了剑。吉安娜和她的卫兵赶来要活捉他，因为死去的叛徒什么也说不出来。塞拉摩的女士向那些揭露真相的人默默致谢。她无法公开感谢他们。亨德尔对暴风城失踪的国王知道些什么，那是她的审讯者要查明的事。]=],
		},
	},
	mentions = {
		{ text = "失踪的外交官" },
		{ text = "失踪的外交官" },
	},
	bonds = {
		{ id = "daelin-proudmoore", name = "戴林·普罗德摩尔", note = "她的父亲" },
		{ id = "arthas-menethil", name = "阿尔萨斯·米奈希尔", note = "她的同伴，也是她失去的爱人" },
		{ id = "thrall", name = "萨尔", note = "她在和平中的盟友" },
		{ id = "aegwynn", name = "艾格文", note = "据说曾指点过她" },
		{ id = "tapoke-slim-jahn", name = "塔珀克 \"瘦子\" 贾恩", note = "参与了被她的卫兵揭穿的阴谋" },
	},
})

Translate("zhCN", "khadgar", {
	title = "卡德加",
	subtitle = "最后的守护者的学徒",
	allegiance = "肯瑞托 · 洛丹伦联盟",
	sections = {
		{
			title = "概述",
			text = [=[卡德加是{link:dalaran}达拉然{/link}的一位年轻法师，被{link:kirin-tor}肯瑞托{/link}派去担任最后一位{link:tirisfal-glades}提瑞斯法{/link}守护者{link:medivh}麦迪文{/link}的学徒。他是第一个看出守护者本人把{link:orcs}兽人{/link}带到{link:azeroth}艾泽拉斯{/link}的人。他参加了{link:first-war}第一次战争{/link}和{link:second-war}第二次战争{/link}，成为他那个时代的伟大大法师之一。很久以前，他穿过了{link:dark-portal}黑暗之门{/link}，再也没有回来。]=],
		},
		{
			title = "意义",
			text = [=[卡德加把真相带出了{link:karazhan}卡拉赞{/link}。没有他，{link:stormwind-city}暴风城{/link}也许永远不会知道它真正的敌人是谁。在{link:second-war}第二次战争{/link}中，他作为{link:alliance}联盟{/link}的一位领袖站在{link:anduin-lothar}安度因·洛萨{/link}身旁，最终他以自己无法归来为代价，关闭了世界之间的道路。]=],
		},
		{
			title = "卡拉赞",
			text = [=[{link:dalaran}达拉然{/link}的法师们早就想知道{link:karazhan}麦迪文之塔{/link}的秘密。他们派卡德加去当他的学徒，并嘱咐他留心观察。守护者收留并教导了他。卡德加很快发现，他的导师常常长久地沉默，看到奇怪的幻象，心中藏着一片他不愿谈及的黑暗。他与作为{link:horde}部落{/link}使者来到塔中的半{link:orcs}兽人{/link}{link:garona}迦罗娜{/link}一起发现，正是{link:medivh}麦迪文{/link}本人打开了{link:dark-portal}黑暗之门{/link}。他们二人把警告带给了{link:llane-wrynn}莱恩·乌瑞恩{/link}国王。随后，卡德加与{link:anduin-lothar}洛萨{/link}一同登上卡拉赞，面对他的导师。麦迪文被杀。在那场战斗中，这位年轻法师在一瞬间老了许多岁，从塔上下来时已是一张老人的面孔。]=],
		},
		{
			title = "第二次战争",
			text = [=[卡德加随{link:anduin-lothar}洛萨{/link}和{link:stormwind-city}暴风城{/link}的流亡者一同北上。在{link:lordaeron}洛丹伦{/link}，他与圣骑士{link:turalyon}图拉扬{/link}一同担任这位勇士的副手。他在北方诸王国与{link:horde}部落{/link}作战，帮助在{link:blackrock-mountain}黑石山{/link}击败了部落。战争胜利后，{link:alliance}联盟{/link}摧毁了{link:dark-portal}黑暗之门{/link}。]=],
		},
		{
			title = "事迹",
			text = [=[• 他在{link:karazhan}卡拉赞{/link}担任{link:medivh}麦迪文{/link}的最后一位学徒。
• 他揭露了麦迪文在{link:orcs}兽人{/link}到来一事中的作用，并警告了{link:llane-wrynn}莱恩国王{/link}。
• 麦迪文被杀时，他与{link:anduin-lothar}安度因·洛萨{/link}并肩作战。
• 他在{link:second-war}第二次战争{/link}中担任{link:alliance}联盟{/link}的副手。
• 战后，他率领联盟穿越了{link:dark-portal}黑暗之门{/link}。]=],
		},
		{
			title = "黑暗之门的彼端",
			text = [=[{link:second-war}第二次战争{/link}之后的几年，{link:dark-portal}黑暗之门{/link}再次打开。{link:orcs}兽人{/link}受老萨满祭司{link:ner-zhul}耐奥祖{/link}派遣，从{red:draenor}德拉诺{/red}穿过它而来，窃取强大的圣物。{link:alliance}联盟{/link}派出一支军队追击他们，进入了兽人的故乡世界。卡德加与{link:turalyon}图拉扬{/link}一同率领这支军队。耐奥祖的法术把德拉诺撕裂了。为了不让这场毁灭蔓延到{link:azeroth}艾泽拉斯{/link}，联盟的领袖们选择从彼端关闭黑暗之门。他们知道自己无法回家了。黑暗之门归于沉寂，远征军从此与故乡失去了联系。]=],
		},
		{
			title = "结局",
			text = [=[自{link:dark-portal}黑暗之门{/link}关闭以来，没有任何关于卡德加的消息传到诸王国。在{link:blasted-lands}诅咒之地{/link}，{link:kirin-tor}肯瑞托{/link}的法师们从{link:nethergarde-keep}守望堡{/link}监视着这座破败的大门，他们没有忘记他。]=],
		},
		{ title = "无从记载", text = "诸王国的任何编年史都没有讲述卡德加和他的同伴们在{link:dark-portal}黑暗之门{/link}彼端的遭遇。" },
	},
	bonds = {
		{ id = "medivh", name = "麦迪文", note = "他的导师" },
		{ id = "garona", name = "迦罗娜", note = "他在卡拉赞的盟友" },
		{ id = "anduin-lothar", name = "安度因·洛萨", note = "他的指挥官" },
		{ id = "turalyon", name = "图拉扬", note = "他在两场战争中的同伴" },
		{ id = "ner-zhul", name = "耐奥祖", note = "他在黑暗之门彼端的敌人" },
	},
})

Translate("zhCN", "turalyon", {
	title = "图拉扬",
	subtitle = "第二次战争的胜利者",
	allegiance = "白银之手骑士团 · 洛丹伦联盟",
	sections = {
		{
			title = "概述",
			text = [=[图拉扬是{link:holy-light}圣光{/link}的一位年轻牧师，后来成为白银之手骑士团的第一批圣骑士之一。他在{link:second-war}第二次战争{/link}中担任{link:anduin-lothar}安度因·洛萨{/link}的副手。洛萨倒下后，图拉扬接过了他的指挥权，赢得了战争。此后，他率领{link:alliance}联盟{/link}穿越了{link:dark-portal}黑暗之门{/link}，再也没有回来。]=],
		},
		{
			title = "意义",
			text = [=[正是图拉扬把{link:alliance}联盟{/link}最黑暗的时刻变成了胜利。他在{link:blackrock-mountain}黑石山{/link}的冲锋击溃了旧{link:horde}部落{/link}，北方诸王国一代人所享有的和平，是他赠予的礼物。]=],
		},
		{
			title = "白银之手",
			text = [=[{link:stormwind-city}暴风城{/link}的流亡者北上时，图拉扬是{link:lordaeron}洛丹伦{/link}教会的一名牧师。{link:anduin-lothar}洛萨{/link}在他身上看到了力量，让他与法师{link:khadgar}卡德加{/link}一同担任自己的副手。图拉扬怀疑自己，也怀疑自己的信仰。然而，他与{link:uther-the-lightbringer}光明使者乌瑟尔{/link}、{link:tirion-fordring}提里奥·弗丁{/link}等少数几人一样，是大主教{link:alonsus-faol}阿隆索斯·法奥{/link}最早训练在战斗中运用{link:holy-light}圣光{/link}的骑士之一。他在北方率领{link:alliance}联盟{/link}的军队对抗{link:horde}部落{/link}，并学会了信任自己被赋予的力量。]=],
		},
		{
			title = "黑石山",
			text = [=[战争末期，{link:alliance}联盟{/link}把{link:horde}部落{/link}向南驱赶到{link:blackrock-mountain}黑石山{/link}。在山脚下的战斗中，大酋长{link:orgrim-doomhammer}奥格瑞姆·毁灭之锤{/link}杀死了{link:anduin-lothar}洛萨{/link}。联盟的士兵动摇了。图拉扬拾起指挥官的剑，重新集结了他们。圣骑士们召唤{link:holy-light}圣光{/link}，部落被击溃。毁灭之锤被俘。图拉扬把最后的{link:orcs}兽人{/link}追击到{link:dark-portal}黑暗之门{/link}，联盟摧毁了这座大门。]=],
		},
		{
			title = "事迹",
			text = [=[• 他是白银之手的第一批圣骑士之一。
• 他在{link:second-war}第二次战争{/link}中担任{link:anduin-lothar}安度因·洛萨{/link}的副手。
• 洛萨死后，他重振{link:alliance}联盟{/link}，赢得了{link:blackrock-mountain}黑石山{/link}之战。
• 他把{link:horde}部落{/link}赶到{link:dark-portal}黑暗之门{/link}，并见证了它被摧毁。
• 他与{link:khadgar}卡德加{/link}一同率领联盟的军队进入{red:draenor}德拉诺{/red}。]=],
		},
		{
			title = "黑暗之门的彼端",
			text = [=[几年后，{link:dark-portal}黑暗之门{/link}再次打开，{link:orcs}兽人{/link}穿过它而来，为萨满祭司{link:ner-zhul}耐奥祖{/link}窃取强大的圣物。图拉扬与{link:khadgar}卡德加{/link}一同率领{link:alliance}联盟{/link}的军队进入德拉诺。与他们同行的有{link:sylvanas-windrunner}希尔瓦娜斯·风行者{/link}的姐姐、游侠奥蕾莉亚·风行者，以及那场战争中的其他英雄。远征军在兽人破碎的世界上与他们作战。当耐奥祖的法术开始撕裂德拉诺时，远征军的领袖们从彼端关闭了黑暗之门，以免这场毁灭波及{link:azeroth}艾泽拉斯{/link}。他们无法回家了。]=],
		},
		{
			title = "结局",
			text = [=[自{link:dark-portal}黑暗之门{/link}关闭以来，诸王国再也没有人见过图拉扬。北方的圣骑士们至今仍把他的名字与{link:uther-the-lightbringer}乌瑟尔{/link}的名字相提并论。]=],
		},
		{ title = "无从记载", text = "诸王国的任何编年史都没有记载图拉扬在{link:dark-portal}黑暗之门{/link}彼端的遭遇。" },
	},
	bonds = {
		{ id = "anduin-lothar", name = "安度因·洛萨", note = "他的指挥官" },
		{ id = "khadgar", name = "卡德加", note = "他在两场战争中的同伴" },
		{ id = "uther-the-lightbringer", name = "光明使者乌瑟尔", note = "白银之手的兄弟" },
		{ id = "orgrim-doomhammer", name = "奥格瑞姆·毁灭之锤", note = "被他击败的大酋长" },
		{ id = "alonsus-faol", name = "阿隆索斯·法奥", note = "册封了他" },
	},
})

Translate("zhCN", "tirion-fordring", {
	title = "提里奥·弗丁",
	subtitle = "被放逐的圣骑士",
	found = "东瘟疫之地西缘河边的一间孤零零的小屋",
	hint = "到东瘟疫之地西缘，寻找那位在小屋旁钓鱼的隐士。",
	allegiance = "无（曾属白银之手骑士团）",
	aliases = { "提里奥" },
	sections = {
		{
			title = "概述",
			text = [=[提里奥·弗丁曾是玛登霍尔德城堡的领主，也是白银之手的第一批圣骑士之一。他因为保护一个{link:orcs}兽人{/link}而被剥夺了土地和头衔，遭到放逐。他如今独自住在{link:eastern-plaguelands}东瘟疫之地{/link}的一间小屋里，是亡者之地中的一位老人。他的儿子在{link:hearthglen}壁炉谷{/link}领导着{link:scarlet-crusade}血色十字军{/link}，并以为他的父亲早已死去。]=],
		},
		{
			title = "意义",
			text = [=[提里奥是一个{link:holy-light}圣光{/link}之人，在他的骑士团和他的王国都不愿坚守荣誉时，他坚守住了自己的荣誉。{link:lordaeron}洛丹伦{/link}很少有人记得他。然而知道他故事的{link:orcs}兽人{/link}尊敬他，他堕落的故事会触动每一个曾不得不在法律与正义之间作出选择的人。]=],
		},
		{
			title = "白银之手",
			text = [=[提里奥与{link:uther-the-lightbringer}光明使者乌瑟尔{/link}和{link:turalyon}图拉扬{/link}一样，是大主教{link:alonsus-faol}阿隆索斯·法奥{/link}训练的第一批骑士之一。他在{link:second-war}第二次战争{/link}中与{link:horde}部落{/link}作战。战后，他与妻子卡兰德拉和儿子{link:taelan-fordring}泰兰{/link}一起，从玛登霍尔德城堡统治着{link:hearthglen}壁炉谷{/link}一带的土地。]=],
		},
		{
			title = "审判",
			text = [=[有一天，提里奥在自己领地附近的废墟中撞见了一个躲藏着的老{link:orcs}兽人{/link}战士。那是{link:eitrigg}伊崔格{/link}。这个兽人本可以杀死他，却饶了他一命。提里奥在他身上看到了荣誉，放他离去。当他自己的士兵前来杀死这个兽人时，提里奥保护了他。为此，他以叛国罪受审。他被剥夺了土地和头衔，被逐出了骑士团。他的妻子告诉他们的儿子，他已经死了，{link:taelan-fordring}泰兰{/link}被带到了他父亲的假墓前。]=],
		},
		{
			title = "事迹",
			text = [=[• 他是白银之手骑士团的第一批圣骑士之一。
• 他在{link:second-war}第二次战争{/link}中与{link:horde}部落{/link}作战。
• 他统治着玛登霍尔德城堡和{link:hearthglen}壁炉谷{/link}周围的土地。
• 他饶了{link:orcs}兽人{/link}{link:eitrigg}伊崔格{/link}，并保护他免遭自己部下的毒手。]=],
		},
		{
			title = "当今之世",
			text = [=[提里奥独自住在河边，远离任何道路。他的儿子{link:taelan-fordring}泰兰{/link}长大后成了一名圣骑士，如今是{link:hearthglen}壁炉谷{/link}{link:scarlet-crusade}血色十字军{/link}的大领主，效忠于一个已经迷失了方向的组织。{link:eitrigg}伊崔格{/link}在{link:orgrimmar}奥格瑞玛{/link}为{link:thrall}萨尔{/link}效力，没有忘记那个救过他的人。]=],
		},
	},
	chapters = {
		{
			title = "救赎",
			hint = "与河边的老人坐在一起，听他讲述他的故事。",
			text = [=[提里奥只请他的客人坐下来听。他讲述了自己的堕落，讲述了在没有他的情况下长大的儿子。他没有请求为自己恢复名誉。他请求的是把{link:taelan-fordring}泰兰{/link}从十字军把他变成的样子中拯救出来。]=],
		},
		{
			title = "被遗忘的记忆",
			hint = "从瘟疫之地南部的一座假墓中找回一件玩具。",
			text = [=[{link:taelan-fordring}泰兰{/link}七岁时，父亲送给他一把小战锤，是他自己那把的仿制品。提里奥被放逐后，男孩把它埋在了地下墓穴中他父亲的假墓里。它从此一直躺在那里，提里奥请人把它取回来。]=],
		},
		{
			title = "失落的荣誉",
			hint = "找回泰兰在北谷扔下的东西。",
			text = [=[{link:uther-the-lightbringer}乌瑟尔{/link}倒下、白银之手被摧毁时，年轻的{link:taelan-fordring}泰兰{/link}尽可能久地坚持战斗。他在{link:northdale}北谷{/link}小村作了最后的抵抗，并在那里把骑士团的旗帜扔在地上，转身离去。提里奥望着那面破碎的旗帜，想起了自己宣誓的那一天。]=],
		},
		{
			title = "梦中",
			hint = "把泰兰带到他父亲身边。",
			text = [=[多年来，{link:taelan-fordring}泰兰{/link}一直梦见他的父亲。想起自己曾经是什么样的人，他离开{link:hearthglen}壁炉谷{/link}去寻找父亲。十字军在路上追捕他，大检察官伊森利恩当着他父亲的面杀死了他。悲痛之中，提里奥宣告他曾效力的骑士团并没有死去。他自封为一个从旧骑士团中重生的新白银之手的大领主。]=],
		},
	},
	mentions = {
		{ text = "救赎" },
		{ text = "被遗忘的记忆" },
		{ text = "失落的荣誉" },
		{ text = "爱与家庭" },
		{ text = "梦中" },
	},
	bonds = {
		{ id = "eitrigg", name = "伊崔格", note = "他饶过的兽人" },
		{ id = "uther-the-lightbringer", name = "光明使者乌瑟尔", note = "白银之手的兄弟" },
		{ id = "alonsus-faol", name = "阿隆索斯·法奥", note = "他在圣光之道上的导师" },
		{ id = "turalyon", name = "图拉扬", note = "白银之手的兄弟" },
	},
})

Translate("zhCN", "garona", {
	title = "迦罗娜",
	subtitle = "半兽人",
	allegiance = "不明（曾属暗影议会）",
	sections = {
		{
			title = "概述",
			text = [=[迦罗娜是一个混血的半{link:orcs}兽人{/link}，{link:first-war}第一次战争{/link}中{link:horde}部落{/link}的间谍和使者。术士{link:gul-dan}古尔丹{/link}派她前往{link:medivh}麦迪文{/link}的高塔。她在那里与年轻的法师{link:khadgar}卡德加{/link}结为朋友，后来又为{link:stormwind-city}暴风城{/link}的{link:llane-wrynn}莱恩·乌瑞恩{/link}国王效力。她也杀害了他。]=],
		},
		{
			title = "意义",
			text = [=[迦罗娜帮助把{link:medivh}麦迪文{/link}背叛的真相带到了{link:stormwind-city}暴风城{/link}，也是她给了暴风城国王致命的一击。这两件事都是她做的，却又都不完全出自她本意。]=],
		},
		{
			title = "使者与间谍",
			text = [=[迦罗娜因为混血而受到{link:orcs}兽人{/link}的鄙视，很早就学会了凭机智求生。{link:gul-dan}古尔丹{/link}的{link:shadow-council}暗影议会{/link}利用了她。她作为{link:horde}部落{/link}派往守护者的使者来到{link:karazhan}卡拉赞{/link}。她和{link:khadgar}卡德加{/link}在那里发现，正是{link:medivh}麦迪文{/link}本人把兽人带到了{link:azeroth}艾泽拉斯{/link}。守护者被杀时，她与卡德加和{link:anduin-lothar}安度因·洛萨{/link}站在一起。此后，她在{link:stormwind-city}暴风城{/link}任职，成为国王信任的谋士。]=],
		},
		{
			title = "事迹",
			text = [=[• 她作为{link:horde}部落{/link}派往{link:medivh}麦迪文{/link}的使者前往{link:karazhan}卡拉赞{/link}。
• 她帮助{link:khadgar}卡德加{/link}揭露了麦迪文的背叛。
• 守护者死时她在场。
• 她在{link:llane-wrynn}莱恩·乌瑞恩{/link}国王自己的要塞中杀死了他。]=],
		},
		{
			title = "结局",
			text = [=[迦罗娜的心智并不属于她自己。{link:shadow-council}暗影议会{/link}的术士们对她的意志拥有一种隐秘的控制力。当{link:orgrim-doomhammer}奥格瑞姆·毁灭之锤{/link}最后一次围攻{link:stormwind-city}暴风城{/link}时，她在{link:raene-wolfrunner}莱恩{/link}的寝宫中杀死了他，年幼的王子{link:varian-wrynn}瓦里安·乌瑞恩{/link}目睹了这一切。随后她逃走了。诸王国中无人知道她去了哪里。]=],
		},
		{ title = "无从记载", text = "{link:stormwind-city}暴风城{/link}陷落以来迦罗娜去了哪里，她是否仍然活着，编年史都没有说。" },
	},
	bonds = {
		{ id = "llane-wrynn", name = "莱恩·乌瑞恩", note = "她的国王，也是她的受害者" },
		{ id = "khadgar", name = "卡德加", note = "她在卡拉赞的朋友" },
		{ id = "medivh", name = "麦迪文", note = "她作为使者所侍奉的守护者" },
		{ id = "gul-dan", name = "古尔丹", note = "她的主人" },
	},
})

Translate("zhCN", "alexstrasza", {
	title = "阿莱克丝塔萨",
	subtitle = "红龙女王",
	allegiance = "红龙军团",
	aliases = { "生命缚誓者阿莱克丝塔萨" },
	sections = {
		{
			title = "概述",
			text = [=[阿莱克丝塔萨是红龙军团的守护巨龙，龙后，生命的守护者。在远古时代，世界的创造者们赋予了她掌管一切生灵的力量。早在精灵建起他们的第一座城市之前，她就一直守望着{link:azeroth}艾泽拉斯{/link}。在{link:second-war}第二次战争{/link}的年代里，她是{link:orcs}兽人{/link}的囚徒，她的孩子们被变成了战争的武器。]=],
		},
		{
			title = "意义",
			text = [=[在所有因{link:deathwing}死亡之翼{/link}的背叛而受苦的种族中，没有哪一个比红龙受苦更深。它们在{link:grim-batol}格瑞姆巴托{/link}的囚禁让{link:horde}部落{/link}得到了巨龙，至今仍是红龙军团与{link:dragonmaw-clan}龙喉氏族{/link}{link:orcs}兽人{/link}之间仇恨的根源。]=],
		},
		{
			title = "守护巨龙",
			text = [=[在远古时代，五头伟大的巨龙被选中守护这个世界。阿莱克丝塔萨是其中最伟大的一位，被立为一切生命的守护者。大地守护者{link:deathwing}耐萨里奥{/link}是她的同伴。在{link:war-of-the-ancients}上古战争{/link}中，他说服守护巨龙们把一部分力量注入他那巨大的{link:ginro-hearthkindle}金{/link}色圆盘巨龙之魂，然后用它来对付他们。巨龙们四散奔逃，红龙军团损失惨重。阿莱克丝塔萨从未忘记此事。]=],
		},
		{
			title = "格瑞姆巴托",
			text = [=[在{link:second-war}第二次战争{/link}中，巨龙之魂落入了{link:dragonmaw-clan}龙喉氏族兽人{/link}之手。他们用它的力量抓住了阿莱克丝塔萨，把她囚禁在{link:wetlands}湿地{/link}的{link:grim-batol}格瑞姆巴托{/link}山下。她每产下一枚龙蛋，他们就拿走一枚，并把她的幼龙养大成为战争坐骑。红龙为{link:horde}部落{/link}作战，对抗{link:alliance}联盟{/link}，焚烧{link:quel-thalas}奎尔萨拉斯{/link}的森林和北方的城镇。]=],
		},
		{
			title = "事迹",
			text = [=[• 她在远古时代被选为生命的守护巨龙。
• 她在{link:war-of-the-ancients}上古战争{/link}中遭到{link:deathwing}耐萨里奥{/link}的背叛。
• 她被{link:dragonmaw-clan}龙喉氏族{/link}囚禁在{link:grim-batol}格瑞姆巴托{/link}。
• 她获得了自由，并亲眼看到巨龙之魂被摧毁。]=],
		},
		{
			title = "当今之世",
			text = [=[战争结束很久之后，{link:dragonmaw-clan}龙喉氏族{/link}仍囚禁着女王。{link:deathwing}死亡之翼{/link}来到{link:grim-batol}格瑞姆巴托{/link}夺取她的龙蛋，想把她的孩子据为己有。一小队英雄和巨龙解救了阿莱克丝塔萨。巨龙之魂被摧毁，她的力量也恢复了。红龙转而攻击囚禁它们的人，并赶走了死亡之翼。龙喉氏族仍盘踞在{link:wetlands}湿地{/link}，红龙仍在追猎他们。龙后本人如今身在何处，很少有凡人知道。]=],
		},
		{ title = "无从记载", text = "诸王国的编年史很少提及龙后获得自由之后去了哪里。" },
	},
	bonds = {
		{ id = "deathwing", name = "死亡之翼", note = "她的守护巨龙同伴，也是背叛她的人" },
		{ id = "queen-azshara", name = "艾萨拉女王", note = "在她的战争中守护巨龙遭到了背叛" },
	},
})

Translate("zhCN", "cenarius", {
	title = "塞纳留斯",
	subtitle = "森林之王",
	allegiance = "卡利姆多的森林 · 塞纳里奥议会",
	sections = {
		{
			title = "概述",
			text = [=[塞纳留斯是荒野的半神，{link:kalimdor}卡利姆多{/link}森林之王。{link:night-elves}暗夜精灵{/link}认为他是他们的月神艾露恩之子。他是{link:malfurion-stormrage}玛法里奥·怒风{/link}的导师，也是凡人德鲁伊技艺之父。他在{link:third-war}第三次战争{/link}中陨落，在{link:ashenvale}灰谷{/link}的林中被{link:grom-hellscream}格罗姆·地狱咆哮{/link}杀死。]=],
		},
		{
			title = "意义",
			text = [=[世上行走的每一位德鲁伊，都走在塞纳留斯开辟的道路上。把{link:night-elves}暗夜精灵{/link}德鲁伊和{link:tauren}牛头人{/link}德鲁伊聚集在一起的{link:cenarion-circle}塞纳里奥议会{/link}，便以他的名字命名。他的死是{link:kalimdor}卡利姆多{/link}森林的一道伤口，暗夜精灵至今没有原谅。]=],
		},
		{
			title = "第一位德鲁伊",
			text = [=[在{link:war-of-the-ancients}上古战争{/link}之前的时代，塞纳留斯住在{link:mount-hyjal}海加尔山{/link}的{link:moonglade}林地{/link}中。他收年轻的{link:malfurion-stormrage}玛法里奥{/link}为学生，教他塑造自然的力量。当{link:burning-legion}燃烧军团{/link}通过{link:well-of-eternity}永恒之井{/link}而来时，塞纳留斯率领森林中的古老之灵与{link:night-elves}暗夜精灵{/link}并肩作战。{link:great-sundering}大分裂{/link}之后，玛法里奥一派的德鲁伊继承了他的教诲，并将其保持了一万年。他的名字在塞纳留斯之角中流传下来，玛法里奥终有一天会在世界之树脚下吹响它。]=],
		},
		{
			title = "他的子女",
			text = [=[塞纳留斯有许多子女。据说树妖和林地守护者都是他的孩子。他的儿子扎尔塔是最初的{link:centaurs}半人马{/link}的父亲，而这个种族如今对他几乎只记得他的愤怒。他的儿子{link:keeper-remulos}雷姆洛斯{/link}守护着{link:moonglade}月光林地{/link}这片神圣的林地。]=],
		},
		{
			title = "事迹",
			text = [=[• 他向{link:malfurion-stormrage}玛法里奥{/link}和最早的德鲁伊传授自然之道。
• 他在{link:war-of-the-ancients}上古战争{/link}中率领森林之灵作战。
• 他守望{link:kalimdor}卡利姆多{/link}的森林一万年。
• 他与前来砍伐{link:ashenvale}灰谷{/link}树木的{link:orcs}兽人{/link}作战。
• 以他命名的号角在{link:battle-of-mount-hyjal}海加尔山之战{/link}中召唤先祖之灵对抗{link:archimonde}阿克蒙德{/link}。]=],
		},
		{
			title = "结局",
			text = [=[{link:third-war}第三次战争{/link}中，战歌氏族的{link:orcs}兽人{/link}来到{link:ashenvale}灰谷{/link}伐木。{link:night-elves}暗夜精灵{/link}与他们交战，塞纳留斯前来保卫他的森林。兽人无法抵挡他。绝望之中，{link:grom-hellscream}格罗姆·地狱咆哮{/link}和他的战士们喝下了被{link:mannoroth}玛诺洛斯{/link}之血污染的泉水，古老的狂怒降临到他们身上。在那股狂怒中，他们杀死了这位半神。塞纳留斯死了。他的德鲁伊仍尊崇他，他的子女仍守护着他的{link:moonglade}林地{/link}。]=],
		},
		{ title = "无从记载", text = "塞纳留斯的力量是否有任何部分在他死后留存下来，编年史没有说。" },
	},
	bonds = {
		{ id = "malfurion-stormrage", name = "玛法里奥·怒风", note = "他的学生" },
		{ id = "grom-hellscream", name = "格罗姆·地狱咆哮", note = "杀死他的人" },
		{ id = "illidan-stormrage", name = "伊利丹·怒风", note = "他学生的兄弟" },
		{ id = "mannoroth", name = "玛诺洛斯", note = "其血使杀死他的人陷入疯狂" },
	},
})

Translate("zhCN", "kil-jaeden", {
	title = "基尔加丹",
	subtitle = "欺诈者",
	allegiance = "燃烧军团",
	aliases = { "欺诈者基尔加丹" },
	sections = {
		{
			title = "概述",
			text = [=[欺诈者基尔加丹是{link:burning-legion}燃烧军团{/link}的大领主之一，只听命于{link:sargeras}萨格拉斯{/link}的意志。他曾与{link:archimonde}阿克蒙德{/link}一同是艾瑞达人的领袖，和阿克蒙德一样接受了黑暗泰坦的许诺。他是谎言大师。正是基尔加丹腐化了{red:draenor}德拉诺{/red}的{link:orcs}兽人{/link}，也正是他造就了{red:lich-king}巫妖王{/red}。]=],
		},
		{
			title = "意义",
			text = [=[上一代人所经历的灾难中，很少有哪一场没有欺诈者插手。他通过{link:ner-zhul}耐奥祖{/link}和{link:gul-dan}古尔丹{/link}把{link:orcs}兽人{/link}变成了一件武器。他通过巫妖王把{link:scourge}天灾军团{/link}释放到了{link:lordaeron}洛丹伦{/link}。与{link:archimonde}阿克蒙德{/link}不同，他从未被击败过。]=],
		},
		{
			title = "艾瑞达人",
			text = [=[很久以前，艾瑞达人由三位领袖统治：基尔加丹、{link:archimonde}阿克蒙德{/link}和维伦。{link:sargeras}萨格拉斯{/link}带着知识与力量的许诺来到他们面前。基尔加丹和阿克蒙德接受了，他们和他们的族人被扭曲成了恶魔。维伦拒绝了，带着他的追随者逃走。基尔加丹因此憎恨他，发誓无论维伦的族人去往何处，都要追杀他们。]=],
		},
		{
			title = "兽人",
			text = [=[维伦的族人德莱尼最终来到了{link:orcs}兽人{/link}居住的德拉诺。基尔加丹在那里找到了他们。他伪装成祖先之灵去见老萨满祭司{link:ner-zhul}耐奥祖{/link}，告诉他德莱尼正在密谋对付他的族人。当耐奥祖开始怀疑他时，欺诈者转向了耐奥祖的学徒{link:gul-dan}古尔丹{/link}，并传授给他{link:fel-magic}邪能魔法{/link}。他通过古尔丹把{link:mannoroth}玛诺洛斯{/link}之血给了兽人，把他们与军团捆绑在一起，并驱使他们攻击德莱尼。]=],
		},
		{
			title = "事迹",
			text = [=[• 他接受了{link:sargeras}萨格拉斯{/link}的许诺，成为军团的领主。
• 他欺骗{link:ner-zhul}耐奥祖{/link}，让{link:orcs}兽人{/link}与德莱尼为敌。
• 他向{link:gul-dan}古尔丹{/link}传授{link:fel-magic}邪能魔法{/link}。
• 他把耐奥祖变成了巫妖王。
• 他派巫妖王为军团的到来准备{link:azeroth}艾泽拉斯{/link}。]=],
		},
		{
			title = "巫妖王",
			text = [=[当{link:ner-zhul}耐奥祖{/link}逃离德拉诺的废墟时，基尔加丹正在等着他。他剥去了萨满祭司的躯体，把他的灵魂禁锢在一套盔甲和一顶头盔中。他把他封在冰中，扔到了{red:northrend}诺森德{/red}，命令他散播一场瘟疫，在军团到来之前削弱这个世界。巫妖王照做了。当{link:archimonde}阿克蒙德{/link}在{link:mount-hyjal}海加尔山{/link}陨落时，欺诈者发现他的仆从已开始挣脱枷锁。]=],
		},
		{
			title = "结局",
			text = [=[基尔加丹从未踏足{link:azeroth}艾泽拉斯{/link}。{link:third-war}第三次战争{/link}之后，他试图借他人之手消灭巫妖王。巫妖王依然存在，欺诈者仍在世界之外注视着。]=],
		},
		{ title = "无从记载", text = "编年史没有说明基尔加丹居于何处，也没有说明他如今在谋划什么。" },
	},
	bonds = {
		{ id = "archimonde", name = "阿克蒙德", note = "他的军团领主同僚" },
		{ id = "sargeras", name = "萨格拉斯", note = "他的主人" },
		{ id = "ner-zhul", name = "耐奥祖", note = "被他欺骗并变成巫妖王的萨满祭司" },
		{ id = "gul-dan", name = "古尔丹", note = "他在兽人中的仆从" },
		{ id = "illidan-stormrage", name = "伊利丹·怒风", note = "被他派去对付巫妖王" },
	},
})

Translate("zhCN", "sargeras", {
	title = "萨格拉斯",
	subtitle = "燃烧军团之主",
	allegiance = "燃烧军团",
	aliases = { "黑暗泰坦" },
	sections = {
		{
			title = "概述",
			text = [=[萨格拉斯是{link:burning-legion}燃烧军团{/link}之主，一位企图毁灭一切造物的堕落泰坦。他曾是泰坦——世界的创造者——中最伟大的勇士，在不可计数的岁月里与扭曲虚空的恶魔作战。久而久之，他对自己的事业感到绝望。他释放了他所囚禁的恶魔，把他们聚集成一支大军，转而对付泰坦所塑造的每一个世界。]=],
		},
		{
			title = "意义",
			text = [=[军团在{link:azeroth}艾泽拉斯{/link}发动的每一场战争，都是以萨格拉斯的名义进行的。他三次触及这个世界：通过{link:queen-azshara}艾萨拉女王{/link}，通过{link:aegwynn}艾格文{/link}和她的儿子{link:medivh}麦迪文{/link}，以及通过被他束缚于自己意志之下的{link:orcs}兽人{/link}。{link:war-of-the-ancients}上古战争{/link}、{link:first-war}第一次战争{/link}和{link:third-war}第三次战争{/link}的背后，都有他的阴影。]=],
		},
		{
			title = "堕落的泰坦",
			text = [=[史书说，萨格拉斯在无尽的黑暗中追猎恶魔，时间之长超出任何凡人的计算。他在那里所见的一切改变了他的心。他开始相信，造物本身就有缺陷，无法修补。他释放了自己抓获的恶魔，并通过{link:archimonde}阿克蒙德{/link}和{link:kil-jaeden}基尔加丹{/link}腐化了艾瑞达人，{link:burning-legion}燃烧军团{/link}就此诞生。]=],
		},
		{
			title = "艾泽拉斯",
			text = [=[一万年前，{link:queen-azshara}艾萨拉女王{/link}和她的上层精灵用{link:well-of-eternity}永恒之井{/link}的力量引起了他的注意。萨格拉斯派他的军团穿过他们的传送门，并试图亲自进入这个世界。在他得逞之前，永恒之井被摧毁了。许多个时代之后，他在{red:northrend}诺森德{/red}的一场巨大风暴中出现在守护者{link:aegwynn}艾格文{/link}面前。她杀死了他的化身，把它的躯体封在海底的一座坟墓中。他的灵魂藏在她体内，进入了她尚未出世的儿子体内。黑暗泰坦通过{link:medivh}麦迪文{/link}打开了{link:dark-portal}黑暗之门{/link}，把{link:orcs}兽人{/link}带到了{link:azeroth}艾泽拉斯{/link}。]=],
		},
		{
			title = "事迹",
			text = [=[• 他曾是泰坦的勇士。
• 他释放了自己囚禁的恶魔，创立了{link:burning-legion}燃烧军团{/link}。
• 他通过{link:archimonde}阿克蒙德{/link}和{link:kil-jaeden}基尔加丹{/link}腐化了艾瑞达人。
• 他向{link:azshara}艾萨拉{/link}低语，几乎进入了这个世界。
• 他藏身于{link:aegwynn}艾格文{/link}和{link:medivh}麦迪文{/link}体内，并通过麦迪文打开了{link:dark-portal}黑暗之门{/link}。]=],
		},
		{
			title = "结局",
			text = [=[萨格拉斯从未以真身行走于{link:azeroth}艾泽拉斯{/link}。他的化身躺在海底的坟墓中，术士{link:gul-dan}古尔丹{/link}曾升起这座坟墓并走了进去，结果送了命。{link:medivh}麦迪文{/link}被杀时，黑暗泰坦对这个世界的控制被打破了。然而他所领导的军团依然存在，它的领主们并没有放弃对这个世界的渴求。]=],
		},
		{ title = "无从记载", text = "{link:medivh}麦迪文{/link}死时萨格拉斯的灵魂怎样了，诸王国的编年史无法说清。" },
	},
	bonds = {
		{ id = "archimonde", name = "阿克蒙德", note = "他的副官" },
		{ id = "kil-jaeden", name = "基尔加丹", note = "他的副官" },
		{ id = "aegwynn", name = "艾格文", note = "杀死了他的化身" },
		{ id = "medivh", name = "麦迪文", note = "他的容器" },
		{ id = "queen-azshara", name = "艾萨拉女王", note = "他的仆从" },
		{ id = "illidan-stormrage", name = "伊利丹·怒风", note = "接受了他的赐予" },
	},
})

Translate("zhCN", "mannoroth", {
	title = "玛诺洛斯",
	subtitle = "毁灭者",
	allegiance = "燃烧军团",
	aliases = { "毁灭者玛诺洛斯" },
	sections = {
		{
			title = "概述",
			text = [=[毁灭者玛诺洛斯是{link:burning-legion}燃烧军团{/link}的一位深渊领主，一个长着角和獠牙的高大恶魔。他在{link:war-of-the-ancients}上古战争{/link}中统率军团的大军。后来，他的血把{red:draenor}德拉诺{/red}的{link:orcs}兽人{/link}与军团捆绑在一起。他在{link:ashenvale}灰谷{/link}被第一个喝下他的血的兽人{link:grom-hellscream}格罗姆·地狱咆哮{/link}杀死。]=],
		},
		{
			title = "意义",
			text = [=[{link:orcs}兽人{/link}的诅咒就是玛诺洛斯之血。它给了他们力量和狂怒，也让他们沦为奴隶。他的死解放了他们，{link:thrall}萨尔{/link}的{link:horde}部落{/link}因此生而自由。]=],
		},
		{
			title = "血",
			text = [=[在{link:war-of-the-ancients}上古战争{/link}中，玛诺洛斯指挥着从{link:well-of-eternity}永恒之井{/link}涌入的恶魔。当军团转向德拉诺时，术士{link:gul-dan}古尔丹{/link}召集{link:orcs}兽人{/link}的酋长们，献上一圣杯深渊领主的血。格罗姆第一个喝下，其他人随后跟着喝了。他们的族人变成了一支被束缚于军团意志之下的狂怒{link:horde}部落{/link}。很久以后，玛诺洛斯在{link:third-war}第三次战争{/link}中来到了{link:ashenvale}灰谷{/link}。当格罗姆和他的战歌氏族对击败森林的守卫者感到绝望时，他们喝下了被玛诺洛斯用自己的血污染的泉水。在随之而来的狂怒中，他们杀死了{link:cenarius}塞纳留斯{/link}。]=],
		},
		{
			title = "事迹",
			text = [=[• 他在{link:war-of-the-ancients}上古战争{/link}中统率军团的大军。
• 他的血把德拉诺的{link:orcs}兽人{/link}与军团捆绑在一起。
• 他污染了{link:ashenvale}灰谷{/link}的一处泉水，再次奴役了战歌氏族。]=],
		},
		{
			title = "结局",
			text = [=[{link:thrall}萨尔{/link}和格罗姆一同在{link:ashenvale}灰谷{/link}的一座峡谷中面对这位深渊领主。玛诺洛斯击倒了萨尔。格罗姆独自冲锋，把战斧劈进恶魔的胸膛。玛诺洛斯死了，{link:orcs}兽人{/link}身上的诅咒被打破。格罗姆因伤重而死。这座峡谷至今仍被称为{link:demon-fall-canyon}屠魔峡谷{/link}。]=],
		},
	},
	bonds = {
		{ id = "grom-hellscream", name = "格罗姆·地狱咆哮", note = "第一个喝下他的血的人，也是杀死他的人" },
		{ id = "gul-dan", name = "古尔丹", note = "把他的血给了兽人" },
		{ id = "archimonde", name = "阿克蒙德", note = "他的军团领主同僚" },
		{ id = "cenarius", name = "塞纳留斯", note = "被他的血所逼疯的人杀死" },
		{ id = "thrall", name = "萨尔", note = "与格罗姆一同和他战斗" },
	},
})
